			.icon(AsgIcon.create(16))
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		flushTask = executor.scheduleWithFixedDelay(this::flush, FLUSH_SECONDS, FLUSH_SECONDS, TimeUnit.SECONDS);
