	@Override
	protected void shutDown()
	{
		flushTask.cancel(false);
		settingsTask.cancel(false);
		pbTask.cancel(false);
		clanTask.cancel(false);
		overlayManager.remove(codewordOverlay);
		executor.execute(this::flush);
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;
	}

