	/**
	 * When the member opens their own collection log, ask the game for every item. This is the one use of
	 * Client.menuAction RuneLite's Plugin Hub rules allow, written exactly as they give it. Re-running the log's init
	 * script afterwards closes the search again, so the log looks as normal.
	 */
	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() != ClogCapture.SETUP_SCRIPT)
		{
			return;
		}
		if (client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) == 1)
		{
			// Someone else's log, opened from their adventure log.
			clogCapture.reset();
			return;
		}
		long now = System.currentTimeMillis();
		if (!isRecording() || now - lastAutoFetchMillis < ClogCapture.AUTO_FETCH_COOLDOWN_MILLIS)
		{
			// Also stops the init script below, which runs setup again, from starting a second fetch.
			return;
		}
		lastAutoFetchMillis = now;
		client.menuAction(-1, InterfaceID.Collection.SEARCH_TOGGLE, MenuAction.CC_OP, 1, -1, "Search", null);
		client.runScript(ClogCapture.INIT_SCRIPT);
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() != ClogCapture.ITEM_SCRIPT || event.getScriptEvent() == null)
		{
			return;
		}
		if (client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) == 1)
		{
			// Someone else's log, opened from their adventure log: never record it as ours.
			clogCapture.reset();
			return;
		}
		if (!isRecording())
		{
			return;
		}
		Object[] args = event.getScriptEvent().getArguments();
		if (args != null && args.length > 2 && args[1] instanceof Integer && args[2] instanceof Integer)
		{
			clogCapture.item((Integer) args[1], (Integer) args[2], client.getTickCount());
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}
		Map<Integer, Integer> captured = clogCapture.finishIfQuiet(client.getTickCount());
		if (captured != null && captured.equals(lastClogCapture))
		{
			// Nothing new since the last read this session (the log is read every time it's opened).
			captured = null;
		}
		if (captured != null)
		{
			lastClogCapture = captured;
			List<ClogCapture.Item> items = ClogCapture.named(captured,
				id -> itemManager.getItemComposition(id).getMembersName());
			pendingClog = new PendingClog(items, client.getVarpValue(VarPlayerID.COLLECTION_COUNT),
				client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX));
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
				"Asgardians Clan: read " + items.size() + " collection log items, sending to the clan website.", null);
			setClogStatus("Sending " + items.size() + " collection log items…", false);
			executor.execute(this::flush);
		}
		if (advLogLoaded)
		{
			advLogLoaded = false;
			String owner = adventureLogOwner(InterfaceID.MenuNew.TITLE);
			advLogOwner = owner != null ? owner : adventureLogOwner(InterfaceID.Menu.LJ_LAYER2);
		}
		if (scrollLoaded)
		{
			scrollLoaded = false;
			Widget text = client.getWidget(InterfaceID.Journalscroll.TEXTLAYER);
			if (text != null && local.getName() != null && local.getName().equals(advLogOwner) && mentionsFastest(text))
			{
				// RuneLite reads these counters into its PB store on this tick; sync once it has.
				configManager.setConfiguration(AsgardiansConfig.GROUP, countersKey(client.getAccountHash()), true);
				pbs.requestSync(System.currentTimeMillis());
				refreshPanel();
			}
		}
	}

	private String adventureLogOwner(int componentId)
	{
		Widget container = client.getWidget(componentId);
		if (container == null)
		{
			return null;
		}
		String own = adventureLogTitle(container.getText());
		if (own != null || container.getChildren() == null)
		{
			return own;
		}
		for (Widget child : container.getChildren())
		{
			String found = child != null ? adventureLogTitle(child.getText()) : null;
			if (found != null)
			{
				return found;
			}
		}
		return null;
	}

	private static String adventureLogTitle(String text)
	{
		String plain = text != null ? Text.removeTags(text) : "";
		return plain.startsWith("The Exploits of ") ? plain.substring("The Exploits of ".length()) : null;
	}

	private static boolean mentionsFastest(Widget layer)
	{
		Widget[] lines = layer.getStaticChildren();
		if (lines == null)
		{
			return false;
		}
		for (Widget line : lines)
		{
			if (line != null && line.getText() != null && line.getText().contains("Fastest"))
			{
				return true;
			}
		}
		return false;
	}

	private static String countersKey(long accountHash)
	{
		return "countersOpened_" + accountHash;
	}

	private boolean chatCommandsEnabled()
	{
		return !"false".equals(configManager.getConfiguration("runelite", "chatcommandsplugin"));
	}

	/** The "Sync all PBs now" button. Executor thread. */
	private void syncPbsNow()
	{
		pbs.requestSyncNow(System.currentTimeMillis());
		flush();
	}

	/** Sends RuneLite's whole PB store. Executor thread; only called from flush with a valid key. */
	private void syncPersonalBests(String address, String key, ApiClient.AccountInfo who)
	{
		if (!syncingPbs.compareAndSet(false, true))
		{
			return;
		}
		pbs.syncStarted();
		List<PersonalBest> all = pbs.snapshot();
		api.syncPersonalBests(address, key, who, all, result ->
		{
			syncingPbs.set(false);
			if (result.ok())
			{
				pbSyncedThisSession.add(who.getHash());
				setPbStatus(all.size() + " PBs synced at "
					+ java.time.LocalTime.now().withNano(0), false);
			}
			else if (result.getStatus() == 401)
			{
				configManager.unsetConfiguration(AsgardiansConfig.GROUP, installKeyName(address, who.getHash()));
				pbs.requestSync(System.currentTimeMillis());
				clientThread.invokeLater(this::ensureRegistered);
			}
			else if (result.getStatus() == 0 || result.getStatus() == 429 || result.getStatus() >= 500)
			{
				pbs.requestSync(System.currentTimeMillis());
				setPbStatus("PB sync failed, will retry", true);
			}
			else
			{
				log.warn("Asgardians rejected PB sync ({}): {}", result.getStatus(), result.getError());
				setPbStatus("The server rejected the PB sync (" + result.getStatus() + ")", true);
			}
		});
	}

	/** Sends the latest captured collection log. Executor thread; only called from flush with a valid key. */
	private void syncCollectionLog(String address, String key, ApiClient.AccountInfo who)
	{
		PendingClog clog = pendingClog;
		if (clog == null || !syncingClog.compareAndSet(false, true))
		{
			return;
		}
		api.syncCollectionLog(address, key, who, clog.getItems(), clog.getObtained(), clog.getTotal(), result ->
		{
			syncingClog.set(false);
			if (result.ok())
			{
				if (pendingClog == clog)
				{
					pendingClog = null;
				}
				configManager.setConfiguration(AsgardiansConfig.GROUP, clogKey(who.getHash()), true);
				setClogStatus(clog.getItems().size() + " collection log items synced at "
					+ java.time.LocalTime.now().withNano(0), false);
			}
			else if (result.getStatus() == 401)
			{
				configManager.unsetConfiguration(AsgardiansConfig.GROUP, installKeyName(address, who.getHash()));
				clientThread.invokeLater(this::ensureRegistered);
			}
			else if (result.getStatus() == 0 || result.getStatus() == 429 || result.getStatus() >= 500)
			{
				setClogStatus("Collection log sync failed, will retry", true);
			}
			else
			{
				if (pendingClog == clog)
				{
					pendingClog = null;
				}
				log.warn("Asgardians rejected collection log sync ({}): {}", result.getStatus(), result.getError());
				setClogStatus("The server rejected the collection log (" + result.getStatus() + ")", true);
			}
		});
	}

	private static String clogKey(long accountHash)
	{
		return "clogSynced_" + accountHash;
	}

	private void setClogStatus(String text, boolean error)
	{
		clogStatus = text;
		clogStatusIsError = error;
		refreshPanel();
	}

	private void setPbStatus(String text, boolean error)
	{
		pbStatus = text;
		pbStatusIsError = error;
		refreshPanel();
	}

	private void recordLoot(String source, Integer npcId, Collection<ItemStack> stacks, boolean withParty)
	{
		if (!isRecording() || stacks.isEmpty())
		{
			return;
		}
		Map<Integer, Integer> merged = new LinkedHashMap<>();
		for (ItemStack stack : stacks)
		{
			merged.merge(itemManager.canonicalize(stack.getId()), stack.getQuantity(), Integer::sum);
		}
		Record record = recorder.loot(source, npcId, merged, withParty ? partySize() : null, client.getWorld(),
			System.currentTimeMillis());
		if (record != null)
		{
			submit(record, settings.getScreenshots().wantsLoot(record));
		}
	}

	/**
	 * How many players are in the instance, including the player. Only a count: nothing about the other players is
	 * sent (RuneLite doesn't allow plugins to crowdsource other players' names, gear or locations).
	 */
	private int partySize()
	{
		int count = 0;
		for (Player player : client.getTopLevelWorldView().players())
		{
			if (player != null)
			{
				count++;
			}
		}
		return Math.max(count, 1);
	}

	private void submit(Record record, boolean wantsScreenshot)
	{
		boolean screenshot = wantsScreenshot && config.uploadScreenshots();
		record.setScreenshot(screenshot);
		record.awaitingScreenshot = screenshot;
		queue.add(record);
		if (screenshot)
		{
			executor.schedule(() -> clientThread.invokeLater(() -> captureWithoutPrivateChat(record)),
				SCREENSHOT_DELAY_MILLIS, TimeUnit.MILLISECONDS);
		}
		refreshPanel();
	}

	/**
	 * Hides private messages for one frame, takes the screenshot, and puts them back. Fails safe: if they can't be
	 * hidden for certain, the record goes without a picture. Client thread.
	 */
	private void captureWithoutPrivateChat(Record record)
	{
		List<Widget> hidden = new ArrayList<>();
		AtomicBoolean restored = new AtomicBoolean();
		Runnable restore = () ->
		{
			if (restored.compareAndSet(false, true) && !hidden.isEmpty())
			{
				clientThread.invoke(() -> hidden.forEach(widget -> widget.setHidden(false)));
			}
		};
		try
		{
			hide(client.getWidget(InterfaceID.PmChat.CONTAINER), hidden);
			Widget[] roots = client.getWidgetRoots();
			if (roots != null)
			{
				for (Widget root : roots)
				{
					hidePrivateLines(root, 0, hidden);
				}
			}
		}
		catch (RuntimeException e)
		{
			log.warn("Asgardians couldn't check for private messages, skipping the screenshot", e);
			restore.run();
			queue.noScreenshot(record.getId());
			return;
		}
		if (hidden.isEmpty() && chatPrivacy.messagedRecently(System.currentTimeMillis()))
		{
			// A private message was just sent or received but nothing was found to hide, so it may still be on screen.
			queue.noScreenshot(record.getId());
			return;
		}
		drawManager.requestNextFrameListener(image ->
		{
			restore.run();
			takeScreenshot(record, image);
		});
		// If no frame is drawn (client minimised), don't leave chat hidden.
		executor.schedule(restore, 3, TimeUnit.SECONDS);
	}

	private static void hide(Widget widget, List<Widget> hidden)
	{
		if (widget != null && !widget.isHidden())
		{
			widget.setHidden(true);
			hidden.add(widget);
		}
	}

	private void hidePrivateLines(Widget widget, int depth, List<Widget> hidden)
	{
		if (widget == null || depth > 8 || widget.isHidden())
		{
			return;
		}
		String text = widget.getText();
		if (text != null && !text.isEmpty() && chatPrivacy.isPrivate(Text.removeTags(text)))
		{
			hide(widget, hidden);
			return;
		}
		for (Widget[] children : new Widget[][]{widget.getStaticChildren(), widget.getDynamicChildren(), widget.getNestedChildren()})
		{
			if (children != null)
			{
				for (Widget child : children)
				{
					hidePrivateLines(child, depth + 1, hidden);
				}
			}
		}
	}

	private void takeScreenshot(Record record, Image image)
	{
		BufferedImage shot = new BufferedImage(image.getWidth(null), image.getHeight(null), BufferedImage.TYPE_INT_RGB);
		Graphics2D g = shot.createGraphics();
		g.drawImage(image, 0, 0, null);
		g.dispose();
		executor.execute(() ->
		{
			try (ByteArrayOutputStream out = new ByteArrayOutputStream())
			{
				ImageIO.write(shot, "png", out);
				queue.attachScreenshot(record.getId(), out.toByteArray());
			}
			catch (IOException e)
			{
				log.warn("Asgardians screenshot failed", e);
			}
			if (config.saveScreenshots())
			{
				imageCapture.saveScreenshot(shot, fileName(record), "Asgardians", false, false);
			}
		});
	}

	private static String fileName(Record record)
	{
		return record.describe().replaceAll("[^A-Za-z0-9 ()'-]", "").trim();
	}

	/** Recording needs consent, a logged-in clan member, an ordinary world and no server kill switch. */
	private boolean isRecording()
	{
		return config.shareData()
			&& !settings.isKillSwitch()
			&& client.getGameState() == GameState.LOGGED_IN
			&& inClan()
			&& client.getWorldType().stream().noneMatch(IGNORED_WORLDS::contains);
	}

	private boolean inClan()
	{
		ClanSettings clan = client.getClanSettings();
		return clan != null && CLAN_NAME.equalsIgnoreCase(clan.getName());
	}

	// ---- account and registration ----

	/** Captures who is logged in, registers if needed and refreshes the panel. Client thread. */
	private void onAccountState()
	{
		Player local = client.getLocalPlayer();
		if (client.getGameState() == GameState.LOGGED_IN && local != null && local.getName() != null)
		{
			long hash = client.getAccountHash();
			ApiClient.AccountInfo previous = account;
			if (previous != null && previous.getHash() != hash)
			{
				// Records belong to the account that earned them; a switch drops anything still unsent.
				queue.clear();
				me = null;
				leaderboards = List.of();
				pendingClog = null;
				clogCapture.reset();
			}
			account = new ApiClient.AccountInfo(hash, Text.sanitize(local.getName()), accountType());
			if (config.shareData() && inClan())
			{
				ensureRegistered();
				if (!pbSyncedThisSession.contains(hash))
				{
					// Once per session, after RuneLite has loaded this account's stored PBs.
					pbs.requestSync(System.currentTimeMillis());
				}
			}
		}
		sharing = isRecording();
		if (loginNewsPending && sharing)
		{
			// Load straight away at login so unread news appears now, not at the next scheduled reload.
			executor.execute(() -> refreshClan(true));
		}
		refreshPanel();
	}

	private String accountType()
	{
		switch (client.getVarbitValue(VarbitID.IRONMAN))
		{
			case 1:
				return "IRONMAN";
			case 2:
				return "ULTIMATE_IRONMAN";
			case 3:
				return "HARDCORE_IRONMAN";
			case 4:
				return "GROUP_IRONMAN";
			case 5:
				return "HARDCORE_GROUP_IRONMAN";
			case 6:
				return "UNRANKED_GROUP_IRONMAN";
			default:
				return "NORMAL";
		}
	}

	private String installKeyName(String address, long accountHash)
	{
		return "installKey_" + ApiClient.sha256(address.toLowerCase()).substring(0, 16) + "_" + accountHash;
	}

	private String installKey(String address, ApiClient.AccountInfo who)
	{
		return configManager.getConfiguration(AsgardiansConfig.GROUP, installKeyName(address, who.getHash()));
	}

	private void ensureRegistered()
	{
		ApiClient.AccountInfo who = account;
		String address = apiAddress();
		if (who == null || installKey(address, who) != null || !registering.compareAndSet(false, true))
		{
			if (who != null && installKey(address, who) != null && status == null)
			{
				setStatus("Connected as " + who.getRsn(), false);
			}
			return;
		}
		setStatus("Connecting to " + address + "…", false);
		try
		{
			api.register(address, who.getRsn(), who.getHash(), who.getType(), result -> onRegistered(address, who, result));
		}
		catch (IllegalArgumentException e)
		{
			registering.set(false);
			setStatus("The API address isn't valid: " + address, true);
		}
	}

	private void onRegistered(String address, ApiClient.AccountInfo who, ApiClient.RegisterResult result)
	{
		registering.set(false);
		if (result.getInstallKey() != null)
		{
			configManager.setConfiguration(AsgardiansConfig.GROUP, installKeyName(address, who.getHash()), result.getInstallKey());
			setStatus("Connected as " + result.getDisplayName()
				+ (result.isHeld() ? " (held for staff review)" : ""), result.isHeld());
			executor.execute(this::flush);
			executor.execute(() -> refreshClan(true));
			return;
		}
		lastRegisterFailure = System.currentTimeMillis();
		if (result.getStatus() == 0)
		{
			setStatus("Can't reach " + address + ". Will retry.", true);
		}
		else if (result.getStatus() == 403)
		{
			setStatus(who.getRsn() + " isn't on the Asgardians roster yet. Nothing will be sent.", true);
		}
		else if (result.getStatus() == 404)
		{
			setStatus("This server doesn't have the plugin endpoints (404). Check the API address.", true);
		}
		else
		{
			setStatus("Couldn't connect (" + result.getStatus() + ")"
				+ (result.getError() != null ? ": " + result.getError() : ""), true);
		}
	}

	// ---- uploads (executor thread) ----

	/** Runs every few seconds so a debounced PB sync goes out soon after it is due. */
	private void pbSyncTick()
	{
		if (pbs.syncDue(System.currentTimeMillis()))
		{
			flush();
		}
	}

	private void flush()
	{
		ApiClient.AccountInfo who = account;
		boolean pbSyncDue = pbs.syncDue(System.currentTimeMillis()) && sharing;
		boolean clogDue = pendingClog != null;
		if (who == null || (queue.size() == 0 && !pbSyncDue && !clogDue) || settings.isKillSwitch())
		{
			return;
		}
		String address = apiAddress();
		String key = installKey(address, who);
		if (key == null)
		{
			if (System.currentTimeMillis() - lastRegisterFailure > REGISTER_RETRY_MILLIS)
			{
				clientThread.invokeLater(this::ensureRegistered);
			}
			return;
		}
		if (pbSyncDue)
		{
			syncPersonalBests(address, key, who);
		}
		if (clogDue)
		{
			syncCollectionLog(address, key, who);
		}
		if (queue.size() == 0 || !uploading.compareAndSet(false, true))
		{
			return;
		}
		List<Record> batch = queue.takeBatch(System.currentTimeMillis());
		if (batch.isEmpty())
		{
			uploading.set(false);
			return;
		}
		api.submitRecords(address, key, who, batch, queue.screenshotsFor(batch), result ->
		{
			uploading.set(false);
			if (result.ok())
			{
				queue.sent(batch);
				setStatus("Connected as " + who.getRsn(), false);
				if (queue.size() > 0)
				{
					executor.execute(this::flush);
				}
			}
			else if (result.getStatus() == 401)
			{
				// Key revoked or unknown on this server: forget it and register again.
				configManager.unsetConfiguration(AsgardiansConfig.GROUP, installKeyName(address, who.getHash()));
				queue.requeue(batch);
				setStatus("Reconnecting…", false);
				clientThread.invokeLater(this::ensureRegistered);
			}
			else if (result.getStatus() == 0 || result.getStatus() == 429 || result.getStatus() >= 500)
			{
				queue.requeue(batch);
				setStatus("Can't reach " + address + ". Will retry.", true);
			}
			else
			{
				// The server refused the batch. Retry its records one by one so only the bad one is dropped.
				log.warn("Asgardians rejected {} record(s) ({}): {}", batch.size(), result.getStatus(), result.getError());
				if (queue.rejected(batch, result.getError()))
				{
					executor.execute(this::flush);
				}
				else
				{
					setStatus("The server rejected a record: " + result.getError(), true);
				}
			}
		});
	}

	private void fetchSettings()
	{
		try
		{
			api.fetchSettings(apiAddress(), fetched -> settings = fetched);
		}
		catch (IllegalArgumentException e)
		{
			log.debug("Asgardians settings skipped: {}", e.getMessage());
		}
	}

	// ---- panel ----

	private void setStatus(String text, boolean error)
	{
		status = text;
		statusIsError = error;
		refreshPanel();
	}

	/** Safe from any thread: reads game state on the client thread, then updates the panel on the Swing thread. */
	private void refreshPanel()
	{
		if (!client.isClientThread())
		{
			clientThread.invokeLater(this::refreshPanel);
			return;
		}
		Player local = client.getLocalPlayer();
		String rsn = client.getGameState() == GameState.LOGGED_IN && local != null ? local.getName() : null;
		boolean countersOpened = rsn != null
			&& Boolean.parseBoolean(configManager.getConfiguration(AsgardiansConfig.GROUP, countersKey(client.getAccountHash())));
		AsgardiansPanel.State state = new AsgardiansPanel.State(rsn, inClan(), config.shareData(), apiAddress(),
			status, statusIsError, queue.size(), queue.recent(),
			chatCommandsEnabled(), countersOpened, rsn != null && client.getVarbitValue(VarbitID.OPTION_PRECISE_TIMING) == 1,
			pbStatus, pbStatusIsError,
			rsn != null && Boolean.parseBoolean(configManager.getConfiguration(AsgardiansConfig.GROUP, clogKey(client.getAccountHash()))),
			clogStatus, clogStatusIsError, me);
		AsgardiansPanel target = panel;
		if (target != null)
		{
			SwingUtilities.invokeLater(() -> target.update(state));
		}
	}
}

package com.asgardians;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Value;

/** Parses the game and clan messages the drop recorder listens for. Input is chat text with tags already removed. */
final class ChatParsers
{
	/** "Your Vorkath kill count is: 512." / "Your completed Chambers of Xeric count is: 50." */
	private static final Pattern KILL_COUNT = Pattern.compile(
		"^Your (?:completed |subdued )?(.+?) (?:kill |success |completion )?count is: ([\\d,]+)\\.?$");
	/** "You pick the guard's pocket." The same pattern RuneLite's Loot Tracker uses. */
	private static final Pattern PICKPOCKET = Pattern.compile("^You pick (?:the )?.+'s? pocket.*");
	private static final Pattern NEW_CLOG =Pattern.compile("^New item added to your collection log: (.+?)\\.?$");
	/** "Rsn has a funny feeling like he's being followed: Vorki at 1,234 killcount." */
	private static final Pattern CLAN_PET = Pattern.compile(
		"^(.+?) (?:has a funny feeling like .+? (?:being followed|have been followed)|feels something weird sneaking into .+? backpack|feels like .+? acquired something special): (.+?)(?: at .*)?\\.?$");

	@Value
	static class KillCount
	{
		String source;
		int count;
	}

	@Value
	static class PetMessage
	{
		boolean duplicate;
	}

	@Value
	static class ClanPet
	{
		String rsn;
		String petName;
	}

	private ChatParsers()
	{
	}

	static boolean isPickpocket(String message)
	{
		return PICKPOCKET.matcher(message).matches();
	}

	static KillCount killCount(String message)
	{
		Matcher m = KILL_COUNT.matcher(message);
		if (!m.matches())
		{
			return null;
		}
		try
		{
			return new KillCount(m.group(1), Integer.parseInt(m.group(2).replace(",", "")));
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	static String newCollectionLogItem(String message)
	{
		Matcher m = NEW_CLOG.matcher(message);
		return m.matches() ? m.group(1) : null;
	}

	/** The player's own pet message. */
	static PetMessage pet(String message)
	{
		if (message.startsWith("You have a funny feeling like you would have been followed"))
		{
			return new PetMessage(true);
		}
		if (message.startsWith("You have a funny feeling like you're being followed")
			|| message.startsWith("You feel something weird sneaking into your backpack"))
		{
			return new PetMessage(false);
		}
		return null;
	}

	/** The clan broadcast that follows a pet, which names the pet. */
	static ClanPet clanPet(String message)
	{
		Matcher m = CLAN_PET.matcher(message);
		return m.matches() ? new ClanPet(m.group(1), m.group(2)) : null;
	}
}

package com.asgardians;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Locale;
import java.util.regex.Pattern;

/**
 * Recognises private messages so they can be hidden before a screenshot. Screenshots are uploaded and kept, so a private
 * conversation must never be in one. Follows the approach of the Dink and Valiance Clan plugins (both BSD 2-Clause).
 * The names here stay in memory and are never sent anywhere. Thread-safe.
 */
class ChatPrivacy
{
	/** After a private message this recent, a screenshot with nothing to hide can't be trusted, so none is taken. */
	static final long RECENT_MILLIS = 45_000;
	private static final int MAX_NAMES = 30;

	/** "From Name: text" or "To Name: text", maybe after a timestamp. */
	private static final Pattern PRIVATE_LINE = Pattern.compile("^(?:\\[[0-9:]+\\]\\s*)?(?:From|To)\\s+[^:]{1,30}:.*");

	private final Deque<String> names = new ArrayDeque<>();
	private long lastMessageMillis = -RECENT_MILLIS - 1;

	/** Call for every private message, sent or received. */
	synchronized void privateMessage(String name, long now)
	{
		lastMessageMillis = now;
		String clean = clean(name);
		if (!clean.isEmpty())
		{
			names.remove(clean);
			names.addFirst(clean);
			while (names.size() > MAX_NAMES)
			{
				names.removeLast();
			}
		}
	}

	synchronized boolean messagedRecently(long now)
	{
		return now - lastMessageMillis < RECENT_MILLIS;
	}

	/** Whether a line of on-screen text, with tags removed, is or may be a private message. */
	synchronized boolean isPrivate(String text)
	{
		String plain = text.replace(' ', ' ').trim();
		if (PRIVATE_LINE.matcher(plain).matches())
		{
			return true;
		}
		String lower = clean(plain);
		for (String name : names)
		{
			if (lower.contains(name + ":") || lower.contains(name + " :"))
			{
				return true;
			}
		}
		return false;
	}

	private static String clean(String text)
	{
		return text == null ? "" : text.replace(' ', ' ').trim().toLowerCase(Locale.UK);
	}
}

package com.asgardians;

import java.time.Instant;
import java.util.List;
import lombok.Data;

/** What the read-only endpoints return: events, teams, boards and announcements. Shapes match PLUGIN_API.md. */
final class ClanData
{
	private ClanData()
	{
	}

	/** GET /plugin/events */
	@Data
	static class EventList
	{
		private List<Event> events;
	}

	@Data
	static class LeaderboardList
	{
		private List<Leaderboard> boards;
	}

	@Data
	static class Leaderboard
	{
		private String title;
		/** e.g. "November so far". */
		private String subtitle;
		/** When the competition ends; only sent for the current BOTW or SOTW. */
		private String endsAt;
		private List<LeaderboardRow> rows;
		/** The member's own row; null when they aren't on this board. */
		private LeaderboardRow me;

		Instant ends()
		{
			return parse(endsAt);
		}

		/** The member's row when the top rows don't already include it. */
		LeaderboardRow rowBelowTop()
		{
			if (me == null)
			{
				return null;
			}
			for (LeaderboardRow row : ClanView.orEmpty(rows))
			{
				if (DropRecorder.sameRsn(row.getRsn(), me.getRsn()))
				{
					return null;
				}
			}
			return me;
		}
	}

	@Data
	static class LeaderboardRow
	{
		private Integer rank;
		private String rsn;
		/** Already formatted by the website, e.g. "412M" or "1.2M xp". */
		private String value;
	}

	@Data
	static class Event
	{
		private String id;
		private String name;
		/** bingo, botw, sotw, competition or adhoc. */
		private String type;
		/** live, upcoming or finished. */
		private String status;
		private String startsAt;
		private String endsAt;
		/** Only while live. */
		private String codeword;
		private boolean signedUp;
		/** The member's team in this event, if any. */
		private String teamId;
		private boolean hasBoard;
		private String summary;
		private String url;
		/** calendar, bingo, r2r, twisted-rainbow, toz or wom; picks the event's view. */
		private String kind;
		/** Present when the event takes sign-ups. */
		private Signup signup;

		boolean isLive()
		{
			return "live".equals(status);
		}

		/** The member is taking part: signed up, on a team, or listed in the event's sign-ups. */
		boolean isIn()
		{
			return signedUp || teamId != null || (signup != null && signup.isSignedUp());
		}

		boolean isUpcoming()
		{
			return "upcoming".equals(status);
		}

		Instant start()
		{
			return parse(startsAt);
		}

		Instant end()
		{
			return parse(endsAt);
		}
	}

	/** GET /plugin/me: the logged-in member's clan profile. The totals are optional. */
	@Data
	static class Me
	{
		private String rsn;
		/** e.g. deputy_owner, opal, og_gamer. */
		private String rank;
		private Integer daysInClan;
		private Long splitCredit;
		private boolean discordLinked;
		/** How to link Discord, replacing the plugin's own wording when the website sends it. */
		private String discordHelp;
		private boolean held;
		private NextRank nextRank;
		/** How many drops are on record, and their total GE value. */
		private Long drops;
		private Long dropValue;
		private Integer clogObtained;
		private Integer pbs;
		private Integer deaths;
	}

	@Data
	static class NextRank
	{
		private String name;
		private Integer daysRemaining;
		private Long creditRemaining;
	}

	/** An event's sign-up state, from GET /plugin/events. */
	@Data
	static class Signup
	{
		private boolean open;
		private String closesAt;
		private Integer count;
		private Integer cap;
		/** none, signedUp, waitlist or confirmed. */
		private String myStatus;
		/** Buy-in paid; null when there's no buy-in. */
		private Boolean paid;
		private String note;
		private List<Field> form;

		boolean isSignedUp()
		{
			return myStatus != null && !"none".equals(myStatus);
		}

		Instant closes()
		{
			return parse(closesAt);
		}
	}

	/** One question on an event's sign-up form. */
	@Data
	static class Field
	{
		private String key;
		private String label;
		/** text, number, choice, multi, timezone or caTier. */
		private String type;
		private boolean required;
		private Double min;
		private Double max;
		private List<String> options;
	}

	/** GET /plugin/events/{id}/signups */
	@Data
	static class SignupList
	{
		private Integer count;
		private Integer cap;
		private List<SignupEntry> signups;
	}

	@Data
	static class SignupEntry
	{
		private String rsn;
		private String team;
		private String status;
		private Boolean paid;
	}

	/** Reply to POST or DELETE /plugin/events/{id}/signup. */
	@Data
	static class SignupResult
	{
		private String myStatus;
	}

	/** GET /plugin/events/{id}/team, and each entry of /teams. */
	@Data
	static class Team
	{
		private String id;
		private String name;
		/** "#rrggbb", optional. */
		private String colour;
		private String captain;
		/** RSNs. Only on /team. */
		private List<String> members;
		private Integer memberCount;
		private Double points;
		/** What points are called for this event, e.g. "notches", "gp", "tiles". */
		private String pointsLabel;
		private Integer rank;
	}

	/** GET /plugin/events/{id}/teams */
	@Data
	static class TeamList
	{
		private List<Team> teams;
	}

	/** GET /plugin/events/{id}/board */
	@Data
	static class Board
	{
		private List<Tile> tiles;
		private Integer done;
		private Integer total;
	}

	@Data
	static class Tile
	{
		private String id;
		private String name;
		private String description;
		/** Heading the tile sits under, e.g. "Ring 2" or "Chambers of Xeric". Optional. */
		private String group;
		/** needed, pending, accepted or declined. */
		private String state;
		private Double points;
	}

	/** GET /plugin/announcements */
	@Data
	static class AnnouncementList
	{
		private List<Announcement> announcements;
	}

	@Data
	static class Announcement
	{
		private long id;
		private String title;
		private String body;
		private String url;
		private String eventId;
		private String postedAt;
		private String postedBy;

		Instant posted()
		{
			return parse(postedAt);
		}
	}

	static Instant parse(String iso)
	{
		if (iso == null)
		{
			return null;
		}
		try
		{
			return Instant.parse(iso);
		}
		catch (java.time.format.DateTimeParseException e)
		{
			return null;
		}
	}
}

package com.asgardians;

import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Consumer;
import lombok.Value;

/**
 * Loads the Events and News tabs: the event list, then for each relevant event its team, standings and board, plus
 * announcements. The follow-up calls run in parallel; the callback gets one finished view.
 */
class ClanFetcher
{
	@Value
	static class Result
	{
		ClanView view;
		/** Highest HTTP status seen among failures (401 means the install key is no longer valid), or 0. */
		int failureStatus;
	}

	private final ApiClient api;

	ClanFetcher(ApiClient api)
	{
		this.api = api;
	}

	/**
	 * @param withBoards also fetch boards (polled more often than the rest)
	 * @param previous   the last view, whose boards are kept when this fetch skips them
	 */
	void fetch(String address, String key, boolean withBoards, ClanView previous, Consumer<Result> done)
	{
		api.get(ApiClient.endpoint(address, "events"), key, ClanData.EventList.class, events ->
		{
			if (!events.ok())
			{
				ClanView keep = previous != null ? previous : ClanView.empty();
				String error = events.getStatus() == 0
					? "Can't reach the clan website"
					: "Events unavailable (" + events.getStatus() + ")";
				done.accept(new Result(new ClanView(keep.getEvents(), keep.getAnnouncements(), keep.getFetchedAt(), error),
					events.getStatus()));
				return;
			}

			List<ClanData.Event> list = new ArrayList<>();
			for (ClanData.Event event : ClanView.orEmpty(events.getBody().getEvents()))
			{
				if (event.getId() != null && (event.isLive() || event.isUpcoming()))
				{
					list.add(event);
				}
			}

			Map<String, ClanData.Team> teams = new ConcurrentHashMap<>();
			Map<String, List<ClanData.Team>> standings = new ConcurrentHashMap<>();
			Map<String, ClanData.Board> boards = new ConcurrentHashMap<>();
			Map<String, List<ClanData.Announcement>> news = new ConcurrentHashMap<>();
			AtomicInteger failure = new AtomicInteger();

			// Each call takes the "I'm done" callback to run once its response is stored.
			List<Consumer<Runnable>> calls = new ArrayList<>();
			for (ClanData.Event event : list)
			{
				String id = event.getId();
				if (event.getTeamId() != null)
				{
					calls.add(then -> api.get(ApiClient.endpoint(address, "events/" + id + "/team"), key,
						ClanData.Team.class, r -> store(r, failure, body -> teams.put(id, body), then)));
				}
				if (event.isLive())
				{
					calls.add(then -> api.get(ApiClient.endpoint(address, "events/" + id + "/teams"), key,
						ClanData.TeamList.class, r -> store(r, failure, body -> standings.put(id, ClanView.orEmpty(body.getTeams())), then)));
				}
				if (withBoards && event.isLive() && event.isHasBoard() && event.getTeamId() != null)
				{
					calls.add(then -> api.get(ApiClient.endpoint(address, "events/" + id + "/board"), key,
						ClanData.Board.class, r -> store(r, failure, body -> boards.put(id, body), then)));
				}
			}
			calls.add(then -> api.get(ApiClient.endpoint(address, "announcements"), key,
				ClanData.AnnouncementList.class, r -> store(r, failure, body -> news.put("news", ClanView.orEmpty(body.getAnnouncements())), then)));

			Runnable finish = () ->
			{
				List<ClanView.EventView> views = new ArrayList<>();
				for (ClanData.Event event : list)
				{
					ClanData.Board board = boards.get(event.getId());
					if (board == null && !withBoards && previous != null)
					{
						board = previousBoard(previous, event.getId());
					}
					views.add(new ClanView.EventView(event, teams.get(event.getId()),
						standings.getOrDefault(event.getId(), List.of()), board));
				}
				List<ClanData.Announcement> items = news.containsKey("news")
					? news.get("news")
					: (previous != null ? previous.getAnnouncements() : List.of());
				String error = failure.get() != 0 ? "Some clan data couldn't load (" + failure.get() + ")" : null;
				done.accept(new Result(new ClanView(views, items, Instant.now(), error), failure.get()));
			};

			AtomicInteger remaining = new AtomicInteger(calls.size());
			Runnable oneDone = () ->
			{
				if (remaining.decrementAndGet() == 0)
				{
					finish.run();
				}
			};
			for (Consumer<Runnable> call : calls)
			{
				call.accept(oneDone);
			}
		});
	}

	private static <T> void store(ApiClient.GetResult<T> result, AtomicInteger failure, Consumer<T> keep, Runnable then)
	{
		try
		{
			if (result.ok())
			{
				keep.accept(result.getBody());
			}
			else if (result.getStatus() != 404)
			{
				// A 404 just means there's nothing of this kind for the event (no teams yet, say), so it isn't an error.
				failure.accumulateAndGet(Math.max(result.getStatus(), 1), Math::max);
			}
		}
		finally
		{
			then.run();
		}
	}

	private static ClanData.Board previousBoard(ClanView previous, String eventId)
	{
		for (ClanView.EventView view : previous.getEvents())
		{
			if (view.getEvent().getId().equals(eventId))
			{
				return view.getBoard();
			}
		}
		return null;
	}
}

package com.asgardians;

import static com.asgardians.PanelParts.BAD;
import static com.asgardians.PanelParts.Card;
import static com.asgardians.PanelParts.GOOD;
import static com.asgardians.PanelParts.HIGHLIGHT;
import static com.asgardians.PanelParts.QUIET;
import static com.asgardians.PanelParts.TEXT;
import static com.asgardians.PanelParts.TODO;
import static com.asgardians.PanelParts.addCard;
import static com.asgardians.PanelParts.badge;
import static com.asgardians.PanelParts.button;
import static com.asgardians.PanelParts.dotRow;
import static com.asgardians.PanelParts.heading;
import static com.asgardians.PanelParts.small;
import java.awt.Color;
import java.time.Instant;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.swing.JPanel;
import lombok.Value;
import net.runelite.client.util.LinkBrowser;
import net.runelite.client.util.QuantityFormatter;

/** Builds the Events, Leaderboard and News tabs from a {@link ClanView}. Swing thread only. */
final class ClanTabs
{
	/** What the tabs need besides the view itself. */
	@Value
	static class Input
	{
		ClanView view;
		/** Online clan members: lowercased RSN to world. */
		Map<String, Integer> online;
		long lastReadAnnouncementId;
		/** Null when connected; otherwise why the tabs can't load. */
		String notConnected;
		ZoneId zone;
		Instant now;
		/** The API address, whose domain links must be on. */
		String address;
		/** Sign-up lists loaded so far, by event ID. */
		Map<String, ClanData.SignupList> signupLists;
		/** Events whose "Who's signed up" list is open. */
		java.util.Set<String> expanded;
		/** Events with a sign-up or withdraw request in flight. */
		java.util.Set<String> busy;
		List<ClanData.Leaderboard> leaderboards;
	}

	/** What the sign-up buttons do. Called on the Swing thread. */
	interface Actions
	{
		void signUp(ClanData.Event event);

		void withdraw(ClanData.Event event);

		void toggleSignups(ClanData.Event event);
	}

	/**
	 * Links come from the server, so only http(s) links on the clan website's own domain (or its subdomains) are opened,
	 * never anything else a compromised or mistaken server might send.
	 */
	static boolean safeLink(String url, String address)
	{
		okhttp3.HttpUrl link = url != null ? okhttp3.HttpUrl.parse(url) : null;
		okhttp3.HttpUrl api = address != null ? okhttp3.HttpUrl.parse(address) : null;
		if (link == null || api == null)
		{
			return false;
		}
		String site = siteDomain(api.host());
		String host = link.host();
		return host.equals(site) || host.endsWith("." + site);
	}

	/** "dev.asgardiansclan.com" and "asgardiansclan.com" both give "asgardiansclan.com"; IPs and localhost stay as they are. */
	static String siteDomain(String host)
	{
		if (host.matches("[0-9.]+") || host.contains(":") || !host.contains("."))
		{
			return host;
		}
		String[] parts = host.split("\\.");
		return parts[parts.length - 2] + "." + parts[parts.length - 1];
	}

	/** A link to a page on the clan website, or null when it isn't one the plugin will open. */
	private static javax.swing.JLabel websiteLink(String text, String url, Input in)
	{
		return safeLink(url, in.getAddress()) ? PanelParts.link(text, () -> LinkBrowser.browse(url)) : null;
	}

	private static final float LEFT = java.awt.Component.LEFT_ALIGNMENT;

	private ClanTabs()
	{
	}

	static void events(JPanel column, Input in, Runnable refresh, Actions actions)
	{
		column.removeAll();
		if (in.getNotConnected() != null)
		{
			Card card = new Card("Events");
			card.add(small(in.getNotConnected(), QUIET));
			addCard(column, card);
			return;
		}
		ClanView view = in.getView();
		for (String group : ClanView.GROUPS)
		{
			List<ClanView.EventView> events = view.inGroup(group);
			if (events.isEmpty())
			{
				continue;
			}
			addCard(column, PanelParts.section(ClanView.groupLabel(group)));
			// Anything with something to do or see gets its own card; the rest is a schedule.
			List<ClanView.EventView> schedule = new ArrayList<>();
			for (ClanView.EventView event : events)
			{
				boolean competition = "botw".equals(group) || "sotw".equals(group);
				if (event.getEvent().getSignup() != null || (event.getEvent().isLive() && !competition))
				{
					addCard(column, eventCard(event, in, actions));
				}
				else
				{
					schedule.add(event);
				}
			}
			if (!schedule.isEmpty())
			{
				addCard(column, schedule(schedule, in));
			}
		}
		if (view.getFetchedAt() != null && view.getEvents().isEmpty())
		{
			Card card = new Card("Events");
			card.add(small("No events running or coming up right now.", QUIET));
			addCard(column, card);
		}
		addCard(column, footer(view, in, refresh));
	}

	static void leaderboards(JPanel column, Input in, Runnable refresh)
	{
		column.removeAll();
		if (in.getNotConnected() != null)
		{
			Card card = new Card("Leaderboards");
			card.add(small(in.getNotConnected(), QUIET));
			addCard(column, card);
			return;
		}
		for (ClanData.Leaderboard board : in.getLeaderboards())
		{
			addCard(column, leaderboardCard(board, in));
		}
		if (in.getView().getFetchedAt() != null && in.getLeaderboards().isEmpty())
		{
			Card card = new Card("Leaderboards");
			card.add(small("No leaderboards to show right now.", QUIET));
			addCard(column, card);
		}
		addCard(column, footer(in.getView(), in, refresh));
	}

	private static Card leaderboardCard(ClanData.Leaderboard board, Input in)
	{
		Card card = new Card(board.getTitle());
		if (board.getSubtitle() != null)
		{
			card.add(small(board.getSubtitle(), QUIET));
		}
		if (board.ends() != null)
		{
			card.add(small("Ends in " + ClanView.countdown(in.getNow(), board.ends()), QUIET));
		}
		List<ClanData.LeaderboardRow> rows = ClanView.orEmpty(board.getRows());
		if (rows.isEmpty())
		{
			card.add(small("No entries yet.", QUIET));
		}
		card.gap();
		String myName = board.getMe() != null ? board.getMe().getRsn() : null;
		for (ClanData.LeaderboardRow row : rows)
		{
			card.addWide(PanelParts.rankRow(row.getRank(), row.getRsn(), row.getValue(), DropRecorder.sameRsn(row.getRsn(), myName)));
		}
		ClanData.LeaderboardRow mine = board.rowBelowTop();
		if (mine != null)
		{
			card.gap();
			card.addWide(PanelParts.rankRow(mine.getRank(), mine.getRsn(), mine.getValue(), true));
		}
		return card;
	}

	static void news(JPanel column, Input in, Runnable refresh)
	{
		column.removeAll();
		if (in.getNotConnected() != null)
		{
			Card card = new Card("News");
			card.add(small(in.getNotConnected(), QUIET));
			addCard(column, card);
			return;
		}
		List<ClanData.Announcement> items = new ArrayList<>(in.getView().getAnnouncements());
		items.sort((a, b) -> Long.compare(b.getId(), a.getId()));
		for (ClanData.Announcement a : items)
		{
			Card card = new Card(a.getTitle());
			if (a.getId() > in.getLastReadAnnouncementId())
			{
				card.add(badge("NEW", HIGHLIGHT));
			}
			String by = a.getPostedBy() != null ? " by " + a.getPostedBy() : "";
			card.add(small(ClanView.localTime(a.posted(), in.getZone()) + by, QUIET));
			card.gap();
			card.add(small(a.getBody(), TEXT));
			javax.swing.JLabel more = websiteLink("Read more", a.getUrl(), in);
			if (more != null)
			{
				card.gap();
				card.addWide(PanelParts.spread(null, more));
			}
			addCard(column, card);
		}
		if (in.getView().getFetchedAt() != null && items.isEmpty())
		{
			Card card = new Card("News");
			card.add(small("No announcements yet.", QUIET));
			addCard(column, card);
		}
		addCard(column, footer(in.getView(), in, refresh));
	}

	// ---- events ----

	private static Card eventCard(ClanView.EventView live, Input in, Actions actions)
	{
		ClanData.Event event = live.getEvent();
		Card card = new Card(event.getName());
		addWhen(card, event, in);
		String note = event.getSignup() != null ? event.getSignup().getNote() : null;
		if (event.getSummary() != null && !event.getSummary().equals(note))
		{
			card.add(small(event.getSummary(), TEXT));
		}
		if (event.getCodeword() != null)
		{
			card.gap();
			card.add(small("Codeword: " + event.getCodeword(), HIGHLIGHT));
		}
		signups(card, event, in, actions);

		ClanData.Team team = live.getTeam();
		if (team != null)
		{
			card.gap();
			card.add(heading("Your team: " + team.getName()));
			String standing = standing(team);
			if (!standing.isEmpty())
			{
				card.add(small(standing, QUIET));
			}
			for (String member : ClanView.orEmpty(team.getMembers()))
			{
				Integer world = in.getOnline().get(member.toLowerCase(Locale.UK));
				String name = member + (member.equalsIgnoreCase(team.getCaptain()) ? " ★" : "");
				card.addWide(dotRow(world != null ? GOOD : QUIET, name, world != null ? "W" + world : "offline",
					world != null ? "Online on world " + world : "Offline"));
			}
		}
		else if (!event.isIn() && event.getSignup() == null)
		{
			card.gap();
			card.add(small("You're not signed up for this one.", QUIET));
		}

		if (live.getStandings().size() > 1)
		{
			card.gap();
			card.add(heading("Standings"));
			List<ClanData.Team> sorted = new ArrayList<>(live.getStandings());
			sorted.sort((a, b) -> Integer.compare(a.getRank() != null ? a.getRank() : 999, b.getRank() != null ? b.getRank() : 999));
			for (ClanData.Team t : sorted)
			{
				boolean mine = team != null && t.getId() != null && t.getId().equals(team.getId());
				String rank = t.getRank() != null ? "#" + t.getRank() + " " : "";
				card.addWide(dotRow(colour(t.getColour(), mine ? HIGHLIGHT : QUIET), rank + t.getName(), points(t), null));
			}
		}

		ClanData.Board board = live.getBoard();
		if (board != null && board.getTiles() != null && !board.getTiles().isEmpty())
		{
			card.gap();
			String progress = board.getDone() != null && board.getTotal() != null
				? " · " + board.getDone() + " / " + board.getTotal() : "";
			card.add(heading("Your board" + progress));
			addTiles(card, board.getTiles());
			javax.swing.JLabel legend = new javax.swing.JLabel(PanelParts.wrap(PanelParts.dot(GOOD) + " done &nbsp;"
				+ PanelParts.dot(TODO) + " pending &nbsp;" + PanelParts.dot(BAD) + " declined &nbsp;"
				+ PanelParts.dot(QUIET) + " needed"));
			legend.setFont(net.runelite.client.ui.FontManager.getRunescapeSmallFont());
			legend.setForeground(QUIET);
			card.add(legend);
		}

		if (event.getSignup() == null)
		{
			card.gap();
			card.addWide(PanelParts.spread(null, websiteLink("Open on website", event.getUrl(), in)));
		}
		return card;
	}

	/** The countdown, with the exact time on its own line so it doesn't wrap mid-time. */
	private static void addWhen(Card card, ClanData.Event event, Input in)
	{
		card.add(PanelParts.status(event.isLive() ? GOOD : QUIET, event.isLive()
			? "Live, ends in " + ClanView.countdown(in.getNow(), event.end())
			: "Starts in " + ClanView.countdown(in.getNow(), event.start())));
		card.add(small(ClanView.localTime(event.isLive() ? event.end() : event.start(), in.getZone()), QUIET));
	}

	/** "Live, ends in 1d 7h (Tue 3 Nov 00:00)" or "Starts in 4d 7h (Fri 6 Nov 00:00)". */
	private static String when(ClanData.Event event, Input in)
	{
		return event.isLive()
			? "Live, ends in " + ClanView.countdown(in.getNow(), event.end()) + " (" + ClanView.localTime(event.end(), in.getZone()) + ")"
			: "Starts in " + ClanView.countdown(in.getNow(), event.start()) + " (" + ClanView.localTime(event.start(), in.getZone()) + ")";
	}

	private static void addTiles(Card card, List<ClanData.Tile> tiles)
	{
		Map<String, List<ClanData.Tile>> groups = new LinkedHashMap<>();
		for (ClanData.Tile tile : tiles)
		{
			groups.computeIfAbsent(tile.getGroup() != null ? tile.getGroup() : "", g -> new ArrayList<>()).add(tile);
		}
		groups.forEach((group, list) ->
		{
			if (!group.isEmpty())
			{
				card.add(small(group, TEXT));
			}
			for (ClanData.Tile tile : list)
			{
				String tip = tile.getName() + " — " + tile.getState()
					+ (tile.getDescription() != null ? "\n" + tile.getDescription() : "");
				String right = tile.getPoints() != null ? "+" + trim(tile.getPoints()) : null;
				card.addWide(dotRow(tileColour(tile.getState()), tile.getName(), right, tip));
			}
		});
	}

	/** A compact list: what's running now, then what's next, with dates on the right. Hover for the full time. */
	private static Card schedule(List<ClanView.EventView> events, Input in)
	{
		Card card = new Card(null);
		for (ClanView.EventView view : events)
		{
			ClanData.Event event = view.getEvent();
			String tip = when(event, in);
			if (event.isLive())
			{
				card.add(heading(event.getName()));
				addWhen(card, event, in);
				card.gap();
			}
			else
			{
				String name = event.getName() + (event.isIn() ? " ✔" : "");
				card.addWide(dotRow(event.isIn() ? GOOD : QUIET, name, ClanView.shortDate(event.start(), in.getZone()),
					tip + (event.isIn() ? ". You'll get a reminder 15 minutes before." : "")));
			}
		}
		return card;
	}

	/** Sign-up state, the member's own status, Sign up / Withdraw, and the list of who's signed up. */
	private static void signups(Card card, ClanData.Event event, Input in, Actions actions)
	{
		ClanData.Signup s = event.getSignup();
		if (s == null)
		{
			return;
		}
		card.gap();
		boolean full = s.getCap() != null && s.getCount() != null && s.getCount() >= s.getCap();
		String state = !s.isOpen() ? "Sign-ups closed"
			: s.closes() != null ? "Sign-ups close in " + ClanView.countdown(in.getNow(), s.closes()) : "Sign-ups open";
		card.add(PanelParts.status(s.isOpen() ? GOOD : QUIET, state));
		if (s.getCount() != null)
		{
			card.add(small(s.getCount() + (s.getCap() != null ? " of " + s.getCap() : "") + " signed up", QUIET));
		}
		if (s.getNote() != null)
		{
			card.add(small(s.getNote(), TEXT));
		}

		if (s.isSignedUp())
		{
			String status = "waitlist".equals(s.getMyStatus()) ? "You're on the waitlist"
				: "confirmed".equals(s.getMyStatus()) ? "You're confirmed" : "You're signed up";
			card.add(small("✔ " + status, GOOD));
			if (s.getPaid() != null)
			{
				card.add(small(s.getPaid() ? "Buy-in paid" : "Buy-in not paid yet", s.getPaid() ? GOOD : TODO));
			}
		}

		if (in.getBusy().contains(event.getId()))
		{
			card.add(small("Sending…", QUIET));
		}
		else if (s.isOpen())
		{
			card.gap();
			if (s.isSignedUp())
			{
				card.addWide(button("Withdraw", () -> actions.withdraw(event)));
			}
			else
			{
				card.addWide(button(full ? "Join the waitlist" : "Sign up", () -> actions.signUp(event)));
			}
		}

		boolean open = in.getExpanded().contains(event.getId());
		String count = s.getCount() != null ? " (" + s.getCount() + ")" : "";
		card.gap();
		card.addWide(PanelParts.spread(
			PanelParts.link((open ? "Hide sign-ups" : "See who's signed up") + count, () -> actions.toggleSignups(event)),
			websiteLink("Website", event.getUrl(), in)));
		if (open)
		{
			ClanData.SignupList list = in.getSignupLists().get(event.getId());
			if (list == null)
			{
				card.add(small("Loading…", QUIET));
			}
			else if (ClanView.orEmpty(list.getSignups()).isEmpty())
			{
				card.add(small("Nobody yet.", QUIET));
			}
			else
			{
				for (ClanData.SignupEntry entry : list.getSignups())
				{
					Color dot = entry.getPaid() == null ? QUIET : entry.getPaid() ? GOOD : TODO;
					String name = entry.getRsn() + (entry.getTeam() != null ? " · " + entry.getTeam() : "");
					String tip = entry.getPaid() == null ? null : entry.getPaid() ? "Buy-in paid" : "Buy-in not paid yet";
					card.addWide(dotRow(dot, name, statusLabel(entry.getStatus()), tip));
				}
			}
		}
	}

	private static String statusLabel(String status)
	{
		if ("waitlist".equals(status))
		{
			return "waitlist";
		}
		return "confirmed".equals(status) ? "confirmed" : "";
	}

	/** One quiet line under the cards: when it was last loaded and a Refresh link, plus any problem loading. */
	private static JPanel footer(ClanView view, Input in, Runnable refresh)
	{
		JPanel footer = PanelParts.column();
		if (view.getError() != null)
		{
			footer.add(small(view.getError(), BAD));
		}
		String updated = view.getFetchedAt() != null
			? "Updated " + ClanView.clock(view.getFetchedAt(), in.getZone())
			: "Loading…";
		JPanel row = PanelParts.spread(PanelParts.plain(updated, QUIET), PanelParts.link("Refresh", refresh));
		row.setAlignmentX(LEFT);
		row.setMaximumSize(new java.awt.Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		footer.add(row);
		return footer;
	}

	private static String standing(ClanData.Team team)
	{
		StringBuilder out = new StringBuilder();
		if (team.getRank() != null)
		{
			out.append("Rank #").append(team.getRank());
		}
		String points = points(team);
		if (points != null)
		{
			out.append(out.length() > 0 ? " · " : "").append(points);
		}
		return out.toString();
	}

	private static String points(ClanData.Team team)
	{
		if (team.getPoints() == null)
		{
			return null;
		}
		String value = team.getPoints() >= 100_000
			? QuantityFormatter.quantityToStackSize(Math.round(team.getPoints()))
			: trim(team.getPoints());
		return value + (team.getPointsLabel() != null ? " " + team.getPointsLabel() : "");
	}

	private static String trim(double value)
	{
		return value == Math.floor(value) ? String.valueOf((long) value) : String.valueOf(value);
	}

	private static Color tileColour(String state)
	{
		if (state == null)
		{
			return QUIET;
		}
		switch (state)
		{
			case "accepted":
				return GOOD;
			case "pending":
				return TODO;
			case "declined":
				return BAD;
			default:
				return QUIET;
		}
	}

	private static Color colour(String hex, Color fallback)
	{
		try
		{
			return hex != null ? Color.decode(hex) : fallback;
		}
		catch (NumberFormatException e)
		{
			return fallback;
		}
	}
}

package com.asgardians;

import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import lombok.Value;

/**
 * Everything the Events and News tabs show, plus the logic that decides which chat notifications to send. Built from
 * the latest fetch; the plugin swaps in a new one each time. Pure, so it can be tested.
 */
@Value
class ClanView
{
	/** How many unread titles to list in chat at login. */
	private static final int LOGIN_NEWS_TITLES = 3;

	/** An event with whatever was fetched for it. */
	@Value
	static class EventView
	{
		ClanData.Event event;
		ClanData.Team team;
		List<ClanData.Team> standings;
		ClanData.Board board;
	}

	List<EventView> events;
	List<ClanData.Announcement> announcements;
	/** When this was fetched; null before the first fetch. */
	Instant fetchedAt;
	/** Why the last fetch failed, if it did. */
	String error;

	static ClanView empty()
	{
		return new ClanView(List.of(), List.of(), null, null);
	}

	List<EventView> live()
	{
		List<EventView> out = new ArrayList<>();
		for (EventView view : events)
		{
			if (view.getEvent().isLive())
			{
				out.add(view);
			}
		}
		return out;
	}

	List<EventView> upcoming()
	{
		List<EventView> out = new ArrayList<>();
		for (EventView view : events)
		{
			if (view.getEvent().isUpcoming())
			{
				out.add(view);
			}
		}
		out.sort((a, b) ->
		{
			Instant x = a.getEvent().start();
			Instant y = b.getEvent().start();
			return x == null || y == null ? 0 : x.compareTo(y);
		});
		return out;
	}

	long latestAnnouncementId()
	{
		long latest = 0;
		for (ClanData.Announcement a : announcements)
		{
			latest = Math.max(latest, a.getId());
		}
		return latest;
	}

	int unread(long lastReadId)
	{
		int count = 0;
		for (ClanData.Announcement a : announcements)
		{
			if (a.getId() > lastReadId)
			{
				count++;
			}
		}
		return count;
	}

	// ---- groups ----

	/** The groups the Events tab shows, in order. */
	static final List<String> GROUPS = List.of("bingo", "botw", "sotw", "other");

	static String groupLabel(String group)
	{
		switch (group)
		{
			case "bingo":
				return "Bingo events";
			case "botw":
				return "Boss of the Week";
			case "sotw":
				return "Skill of the Week";
			default:
				return "Other events";
		}
	}

	/** Which group an event belongs to. R2R, Twisted Rainbow and Tug of Zaros run as bingo events. */
	static String group(ClanData.Event event)
	{
		String kind = event.getKind() != null ? event.getKind() : "";
		String type = event.getType() != null ? event.getType() : "";
		if ("botw".equals(type) || "sotw".equals(type))
		{
			return type;
		}
		if ("bingo".equals(type) || "bingo".equals(kind) || "r2r".equals(kind) || "twisted-rainbow".equals(kind) || "toz".equals(kind))
		{
			return "bingo";
		}
		return "other";
	}

	/** One group's events: live first, then upcoming, soonest first. */
	List<EventView> inGroup(String group)
	{
		List<EventView> out = new ArrayList<>();
		for (EventView view : live())
		{
			if (group.equals(group(view.getEvent())))
			{
				out.add(view);
			}
		}
		for (EventView view : upcoming())
		{
			if (group.equals(group(view.getEvent())))
			{
				out.add(view);
			}
		}
		return out;
	}

	// ---- notifications ----

	/** Announcements newer than the last one the member was told about, oldest first. */
	List<ClanData.Announcement> newAnnouncements(long lastNotifiedId)
	{
		List<ClanData.Announcement> out = new ArrayList<>();
		for (ClanData.Announcement a : announcements)
		{
			if (a.getId() > lastNotifiedId)
			{
				out.add(a);
			}
		}
		out.sort((a, b) -> Long.compare(a.getId(), b.getId()));
		return out;
	}

	/** A chat line for each bingo-style event the member is in whose buy-in isn't marked as paid. Waitlisted members owe nothing yet. */
	List<String> buyInReminders()
	{
		List<String> lines = new ArrayList<>();
		for (EventView view : inGroup("bingo"))
		{
			ClanData.Event event = view.getEvent();
			ClanData.Signup signup = event.getSignup();
			if (signup != null && signup.isSignedUp() && !"waitlist".equals(signup.getMyStatus())
				&& Boolean.FALSE.equals(signup.getPaid()))
			{
				lines.add("Your buy-in for " + event.getName() + " isn't marked as paid."
					+ (signup.getNote() != null ? " " + signup.getNote() : ""));
			}
		}
		return lines;
	}

	/** The chat lines for unread announcements at login, newest first; empty when everything has been read. */
	List<String> loginNews(long lastReadId)
	{
		List<ClanData.Announcement> unread = newAnnouncements(lastReadId);
		Collections.reverse(unread);
		if (unread.isEmpty())
		{
			return List.of();
		}
		if (unread.size() == 1)
		{
			return List.of("Unread news: " + unread.get(0).getTitle() + ". Open the News tab to read it.");
		}
		List<String> lines = new ArrayList<>();
		lines.add("You have " + unread.size() + " unread announcements. Open the News tab to read them.");
		for (ClanData.Announcement a : unread.subList(0, Math.min(unread.size(), LOGIN_NEWS_TITLES)))
		{
			lines.add("- " + a.getTitle());
		}
		if (unread.size() > LOGIN_NEWS_TITLES)
		{
			lines.add("...and " + (unread.size() - LOGIN_NEWS_TITLES) + " more.");
		}
		return lines;
	}

	/** Tiles of the member's boards whose state changed to accepted or declined since the previous view. */
	List<String> tileChanges(ClanView previous)
	{
		if (previous == null)
		{
			return List.of();
		}
		Map<String, String> before = new HashMap<>();
		for (EventView view : previous.getEvents())
		{
			if (view.getBoard() != null && view.getBoard().getTiles() != null)
			{
				for (ClanData.Tile tile : view.getBoard().getTiles())
				{
					before.put(view.getEvent().getId() + "/" + tile.getId(), tile.getState());
				}
			}
		}
		List<String> out = new ArrayList<>();
		for (EventView view : events)
		{
			if (view.getBoard() == null || view.getBoard().getTiles() == null)
			{
				continue;
			}
			for (ClanData.Tile tile : view.getBoard().getTiles())
			{
				String old = before.get(view.getEvent().getId() + "/" + tile.getId());
				String now = tile.getState();
				if (old != null && !old.equals(now) && ("accepted".equals(now) || "declined".equals(now)))
				{
					out.add(view.getEvent().getName() + ": tile \"" + tile.getName() + "\" was " + now + ".");
				}
			}
		}
		return out;
	}

	/** Events that went live since the previous view (not on the very first fetch, so a login doesn't repeat them). */
	List<ClanData.Event> newlyLive(ClanView previous)
	{
		if (previous == null || previous.getFetchedAt() == null)
		{
			return List.of();
		}
		Set<String> wasLive = new HashSet<>();
		for (EventView view : previous.live())
		{
			wasLive.add(view.getEvent().getId());
		}
		List<ClanData.Event> out = new ArrayList<>();
		for (EventView view : live())
		{
			if (!wasLive.contains(view.getEvent().getId()))
			{
				out.add(view.getEvent());
			}
		}
		return out;
	}

	/** Signed-up events starting within the reminder window that haven't been reminded yet. */
	List<ClanData.Event> dueReminders(Instant now, Duration window, Set<String> alreadyReminded)
	{
		List<ClanData.Event> out = new ArrayList<>();
		for (EventView view : upcoming())
		{
			ClanData.Event event = view.getEvent();
			Instant start = event.start();
			if (event.isIn() && start != null && !alreadyReminded.contains(event.getId())
				&& start.isAfter(now) && !start.isAfter(now.plus(window)))
			{
				out.add(event);
			}
		}
		return out;
	}

	// ---- formatting ----

	private static final DateTimeFormatter WHEN = DateTimeFormatter.ofPattern("EEE d MMM HH:mm", Locale.UK);

	/** "Mon 26 Oct 14:00" in the member's own time zone. */
	static String localTime(Instant instant, ZoneId zone)
	{
		return instant == null ? "?" : WHEN.format(instant.atZone(zone));
	}

	private static final DateTimeFormatter SHORT_DATE = DateTimeFormatter.ofPattern("d MMM", Locale.UK);
	private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("HH:mm", Locale.UK);

	/** "26 Oct", for schedule rows. */
	static String shortDate(Instant instant, ZoneId zone)
	{
		return instant == null ? "?" : SHORT_DATE.format(instant.atZone(zone));
	}

	/** "16:42". */
	static String clock(Instant instant, ZoneId zone)
	{
		return instant == null ? "?" : CLOCK.format(instant.atZone(zone));
	}

	/** "2d 4h", "3h 10m", "12m", "now". */
	static String countdown(Instant from, Instant to)
	{
		if (from == null || to == null)
		{
			return "?";
		}
		long minutes = Duration.between(from, to).toMinutes();
		if (minutes <= 0)
		{
			return "now";
		}
		long days = minutes / (60 * 24);
		long hours = minutes / 60 % 24;
		long mins = minutes % 60;
		if (days > 0)
		{
			return days + "d " + hours + "h";
		}
		if (hours > 0)
		{
			return hours + "h " + mins + "m";
		}
		return mins + "m";
	}

	static String typeLabel(String type)
	{
		if (type == null)
		{
			return "Event";
		}
		switch (type)
		{
			case "botw":
				return "Boss of the week";
			case "sotw":
				return "Skill of the week";
			case "bingo":
				return "Bingo";
			case "competition":
				return "Competition";
			default:
				return "Event";
		}
	}

	static <T> List<T> orEmpty(List<T> list)
	{
		return list == null ? Collections.emptyList() : list;
	}
}

package com.asgardians;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import lombok.Value;

/**
 * Gathers the whole collection log. When the collection log opens, the plugin triggers its Search, the game sends every
 * obtained item and runs script 4100 once per item with its ID and quantity (the approach WikiSync and RuneProfile use).
 * The capture is finished once the script has been quiet for a couple of ticks. Client thread only.
 */
class ClogCapture
{
	/** The game script run once per obtained collection log item. */
	static final int ITEM_SCRIPT = 4100;
	/** Runs when the collection log opens; that's when the plugin asks the game for every item. */
	static final int SETUP_SCRIPT = 7797;
	/** Resets the log view after the search, so the member sees their log as normal. */
	static final int INIT_SCRIPT = 2240;
	/** At most one automatic fetch this often. */
	static final long AUTO_FETCH_COOLDOWN_MILLIS = 60_000;
	/** Ticks without another item before the capture counts as complete. */
	static final int QUIET_TICKS = 2;

	@Value
	static class Item
	{
		int id;
		String name;
		int qty;
	}

	private final Map<Integer, Integer> items = new LinkedHashMap<>();
	private int lastItemTick = -1;

	void item(int itemId, int quantity, int tick)
	{
		if (itemId > 0 && quantity > 0)
		{
			items.merge(itemId, quantity, Math::max);
		}
		lastItemTick = tick;
	}

	/** Drops a capture in progress, e.g. when someone else's log is opened from their adventure log. */
	void reset()
	{
		items.clear();
		lastItemTick = -1;
	}

	/**
	 * @return the captured item IDs and quantities once the capture has gone quiet, else null. Clears the capture.
	 */
	Map<Integer, Integer> finishIfQuiet(int tick)
	{
		if (lastItemTick < 0 || tick <= lastItemTick + QUIET_TICKS)
		{
			return null;
		}
		Map<Integer, Integer> done = new LinkedHashMap<>(items);
		reset();
		return done.isEmpty() ? null : done;
	}

	static List<Item> named(Map<Integer, Integer> captured, java.util.function.IntFunction<String> names)
	{
		List<Item> list = new ArrayList<>();
		captured.forEach((id, qty) -> list.add(new Item(id, names.apply(id), qty)));
		return list;
	}
}

package com.asgardians;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.Locale;
import java.util.function.Supplier;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * While a clan event the member is in is live, shows its codeword and the current UTC time. Overlays are part of
 * RuneLite screenshots, so staff can check a drop screenshot was taken during the event.
 */
class CodewordOverlay extends OverlayPanel
{
	private static final DateTimeFormatter UTC = DateTimeFormatter.ofPattern("d MMM HH:mm:ss 'UTC'", Locale.UK)
		.withZone(ZoneOffset.UTC);

	private final AsgardiansConfig config;
	private final Supplier<ClanView> view;

	CodewordOverlay(AsgardiansPlugin plugin, AsgardiansConfig config, Supplier<ClanView> view)
	{
		super(plugin);
		this.config = config;
		this.view = view;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showCodeword())
		{
			return null;
		}
		ClanView current = view.get();
		boolean any = false;
		for (ClanView.EventView live : current.live())
		{
			ClanData.Event event = live.getEvent();
			if (event.getCodeword() == null || !event.isIn())
			{
				continue;
			}
			if (!any)
			{
				panelComponent.getChildren().add(TitleComponent.builder().text("Asgardians").color(PanelParts.HIGHLIGHT).build());
				any = true;
			}
			panelComponent.getChildren().add(LineComponent.builder().left(event.getName()).build());
			panelComponent.getChildren().add(LineComponent.builder().left("Codeword:").right(event.getCodeword())
				.rightColor(PanelParts.HIGHLIGHT).build());
		}
		if (!any)
		{
			return null;
		}
		panelComponent.getChildren().add(LineComponent.builder().left(UTC.format(Instant.now())).build());
		return super.render(graphics);
	}
}

package com.asgardians;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Data;
import lombok.Value;
import net.runelite.api.gameval.ItemID;

/** What a death record carries: who, where, and what it cost. */
@Data
class Death
{
	@Data
	static class Killer
	{
		/** "npc", "player" or "unknown". Player killers are never named. */
		private final String type;
		private final String name;
		private final Integer npcId;
		private final Integer combatLevel;

		static Killer unknown()
		{
			return new Killer("unknown", null, null, null);
		}

		static Killer player()
		{
			return new Killer("player", null, null, null);
		}
	}

	/** A known activity or area, keyed by map region. */
	@Value
	static class Place
	{
		String name;
		/** Items are kept on death here. */
		boolean safe;
	}

	/** Region IDs of activities where deaths are safe, from Dink's WorldUtils (BSD-2-Clause, pajlads). */
	static final Map<Integer, Place> PLACES = places();

	private Killer killer;
	private int regionId;
	private int plane;
	private boolean instanced;
	/** Name of the activity, when the region is a known one. */
	private String area;
	/** Items are kept on a death here (minigames, raids and similar). */
	private boolean safe;
	private boolean wilderness;
	/** Estimated GE value of what was lost: 0 for safe deaths. */
	private long valueLost;
	/** How many items the player keeps on a dangerous death (3, 0 when skulled, +1 with Protect Item, 0 for UIM). */
	private int keepCount;
	private List<Record.Item> lostItems;

	/** One stack the player had at death. */
	@Value
	static class Held
	{
		int id;
		String name;
		int qty;
		long price;
	}

	@Value
	static class Split
	{
		List<Held> kept;
		List<Held> lost;

		long lostValue()
		{
			long total = 0;
			for (Held held : lost)
			{
				total += held.getPrice() * held.getQty();
			}
			return total;
		}
	}

	/** Bonds are always kept and don't use up a kept slot. */
	private static final Set<Integer> ALWAYS_KEPT = Set.of(ItemID.OSRS_BOND, ItemID.BOUGHT_OSRS_BOND, ItemID.OSRS_BOND_UNTRADEABLE);

	/**
	 * Splits what the player held into kept and lost the way the game does for an ordinary dangerous death: the most
	 * valuable single items are kept, one at a time, up to keepCount.
	 */
	static Split split(List<Held> held, int keepCount)
	{
		List<Held> sorted = new ArrayList<>(held);
		sorted.sort(Comparator.comparingLong(Held::getPrice).reversed());
		List<Held> kept = new ArrayList<>();
		List<Held> lost = new ArrayList<>();
		int keptSoFar = 0;
		for (Held stack : sorted)
		{
			if (ALWAYS_KEPT.contains(stack.getId()))
			{
				kept.add(stack);
				continue;
			}
			int keepHere = Math.min(stack.getQty(), keepCount - keptSoFar);
			if (keepHere > 0)
			{
				kept.add(new Held(stack.getId(), stack.getName(), keepHere, stack.getPrice()));
				keptSoFar += keepHere;
			}
			if (stack.getQty() > keepHere)
			{
				lost.add(new Held(stack.getId(), stack.getName(), stack.getQty() - keepHere, stack.getPrice()));
			}
		}
		return new Split(kept, lost);
	}

	private static Map<Integer, Place> places()
	{
		Map<Integer, Place> map = new java.util.HashMap<>();
		add(map, "Chambers of Xeric", 12889, 13136, 13137, 13138, 13139, 13140, 13141, 13145, 13393, 13394, 13395, 13396, 13397, 13401);
		add(map, "Theatre of Blood", 12611, 12612, 12613, 12867, 12869, 13122, 13123, 13125, 13379);
		add(map, "Tombs of Amascut", 14160, 14162, 14164, 14674, 14676, 15184, 15186, 15188, 15696, 15698, 15700);
		add(map, "The Gauntlet", 7512, 7768, 12127);
		add(map, "The Inferno", 9043);
		add(map, "Fight Caves", 9551);
		add(map, "Fight Pits", 9552);
		add(map, "Fortis Colosseum", 7216);
		add(map, "Nightmare Zone", 9033);
		add(map, "Barbarian Assault", 7508, 7509, 10322);
		add(map, "Castle Wars", 9520, 9620);
		add(map, "Soul Wars", 8493, 8748, 8749, 9005);
		add(map, "Last Man Standing", 13658, 13659, 13660, 13914, 13915, 13916, 13918, 13919, 13920, 14174, 14175, 14176, 14430, 14431, 14432);
		add(map, "Player-owned house", 7257, 7534, 7535, 7790, 7791, 8046, 8047, 8302, 8303);
		add(map, "Clan Wars", 12621, 12622, 12623, 13130, 13131, 13133, 13134, 13135, 13386, 13387, 13390, 13641, 13642, 13643, 13644, 13645, 13646, 13647, 13899, 13900, 14155, 14156);
		add(map, "Creature Graveyard", 13462);
		add(map, "Clan hall", 6997);
		return java.util.Collections.unmodifiableMap(map);
	}

	private static void add(Map<Integer, Place> map, String name, int... regions)
	{
		for (int region : regions)
		{
			map.put(region, new Place(name, true));
		}
	}
}

package com.asgardians;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;

/**
 * Turns game events into generic records. It knows nothing about events or bingo: the server decides what each
 * record counts for. Called on the client thread only.
 */
class DropRecorder
{
	/** How close a kill count message must be to its loot to be attached to it. */
	static final long KC_WINDOW_MILLIS = 10_000;
	/** How long after a pet message the clan broadcast can still name it. */
	static final long PET_WINDOW_MILLIS = 10_000;
	/** How far back a new clog slot looks for the loot that caused it, to find its item ID. */
	static final long CLOG_LOOT_WINDOW_MILLIS = 60_000;
	private static final int RECENT = 20;

	/** What the recorder needs from the game's item data. */
	interface Items
	{
		String name(int itemId);

		/** GE price per item. */
		long price(int itemId);

		/** Item ID for an exact item name, or null when it can't be found. */
		Integer idForName(String name);
	}

	private final Items items;
	private final LinkedList<Record> recentLoot = new LinkedList<>();
	private Record lastPet;
	private String lastKcSource;
	private int lastKc;
	private long lastKcMillis;

	DropRecorder(Items items)
	{
		this.items = items;
	}

	/**
	 * @param stacks item ID to quantity, already merged by item
	 */
	Record loot(String sourceName, Integer npcId, Map<Integer, Integer> stacks, Integer partySize, int world, long now)
	{
		List<Record.Item> list = new ArrayList<>();
		long total = 0;
		for (Map.Entry<Integer, Integer> stack : stacks.entrySet())
		{
			int id = stack.getKey();
			int qty = stack.getValue();
			long price = items.price(id);
			list.add(new Record.Item(id, items.name(id), qty, price));
			total += price * qty;
		}
		if (list.isEmpty())
		{
			return null;
		}

		Record record = newRecord(Record.Type.loot, world, now);
		Record.Source source = new Record.Source(sourceName, npcId);
		if (sameSource(lastKcSource, sourceName) && now - lastKcMillis <= KC_WINDOW_MILLIS)
		{
			source.setKc(lastKc);
		}
		record.setSource(source);
		record.setItems(list);
		record.setPartySize(partySize);
		record.totalValue = total;

		recentLoot.addFirst(record);
		while (recentLoot.size() > RECENT)
		{
			recentLoot.removeLast();
		}
		return record;
	}

	/** Kill count messages can arrive just before or just after the loot, so fill in recent loot from the same source too. */
	void killCount(ChatParsers.KillCount kc, long now)
	{
		lastKcSource = kc.getSource();
		lastKc = kc.getCount();
		lastKcMillis = now;
		for (Record record : recentLoot)
		{
			if (now - record.createdMillis > KC_WINDOW_MILLIS)
			{
				break;
			}
			Record.Source source = record.getSource();
			if (source != null && source.getKc() == null && sameSource(source.getName(), kc.getSource()))
			{
				source.setKc(kc.getCount());
			}
		}
	}

	Record pet(boolean duplicate, int world, long now)
	{
		Record record = newRecord(Record.Type.pet, world, now);
		record.setDuplicate(duplicate);
		Record.Source source = lastKcSource != null && now - lastKcMillis <= KC_WINDOW_MILLIS
			? new Record.Source(lastKcSource, null) : null;
		if (source != null)
		{
			source.setKc(lastKc);
		}
		record.setSource(source);
		lastPet = record;
		return record;
	}

	/** Names the most recent pet from the clan broadcast, if it is ours and recent. */
	void clanPet(ChatParsers.ClanPet broadcast, String localRsn, long now)
	{
		if (lastPet != null && lastPet.getPetName() == null && now - lastPet.createdMillis <= PET_WINDOW_MILLIS
			&& sameRsn(broadcast.getRsn(), localRsn))
		{
			lastPet.setPetName(broadcast.getPetName());
		}
	}

	Record clog(String itemName, Integer completed, int world, long now)
	{
		Record record = newRecord(Record.Type.clog, world, now);
		record.setItemName(itemName);
		record.setItemId(findRecentItemId(itemName, now));
		if (record.getItemId() == null)
		{
			record.setItemId(items.idForName(itemName));
		}
		record.setCompleted(completed);
		return record;
	}

	private Integer findRecentItemId(String itemName, long now)
	{
		Iterator<Record> it = recentLoot.iterator();
		while (it.hasNext())
		{
			Record record = it.next();
			if (now - record.createdMillis > CLOG_LOOT_WINDOW_MILLIS)
			{
				break;
			}
			for (Record.Item item : record.getItems())
			{
				if (item.getName().equalsIgnoreCase(itemName))
				{
					return item.getId();
				}
			}
		}
		return null;
	}

	private static Record newRecord(Record.Type type, int world, long now)
	{
		Record record = new Record(type, Instant.ofEpochMilli(now).toString(), world);
		record.createdMillis = now;
		return record;
	}

	/** The Gauntlet bosses are recorded under the name of the activity. */
	static String npcLootSource(String npcName)
	{
		switch (npcName)
		{
			case "Crystalline Hunllef":
				return "The Gauntlet";
			case "Corrupted Hunllef":
				return "Corrupted Gauntlet";
			default:
				return npcName;
		}
	}

	/** Kill count messages drop a leading "The" ("Your Gauntlet completion count"), loot sources keep it. */
	static boolean sameSource(String a, String b)
	{
		return a != null && b != null && withoutThe(a).equalsIgnoreCase(withoutThe(b));
	}

	private static String withoutThe(String name)
	{
		return name.regionMatches(true, 0, "The ", 0, 4) ? name.substring(4) : name;
	}

	/** RSNs in chat can use non-breaking spaces or underscores where the player name has spaces. */
	static boolean sameRsn(String a, String b)
	{
		return a != null && b != null && normalise(a).equalsIgnoreCase(normalise(b));
	}

	private static String normalise(String rsn)
	{
		return rsn.replace(' ', ' ').replace('_', ' ').replace('-', ' ').trim();
	}
}

package com.asgardians;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/** Shared building blocks for the side panel's tabs, so every tab looks the same. */
final class PanelParts
{
	static final Color GOOD = ColorScheme.PROGRESS_COMPLETE_COLOR;
	static final Color TODO = ColorScheme.PROGRESS_INPROGRESS_COLOR;
	static final Color BAD = ColorScheme.PROGRESS_ERROR_COLOR;
	/** Main text. */
	static final Color TEXT = new Color(0xD8, 0xD8, 0xD8);
	/** Secondary text. RuneLite's medium grey is too dark to read at this font size on the card background. */
	static final Color QUIET = new Color(0xA0, 0xA0, 0xA0);
	static final Color HIGHLIGHT = new Color(0xE8, 0x76, 0x3F);
	static final Color TEST_SERVER = new Color(0xC9, 0xA2, 0x27);
	/** Width text wraps at inside a card. */
	static final int TEXT_WIDTH = 150;
	static final int GAP = 8;
	/** Room for a position up to four digits. */
	private static final int RANK_WIDTH = 26;

	private PanelParts()
	{
	}

	/** A titled dark box that stacks its rows. */
	static class Card extends JPanel
	{
		Card(String title)
		{
			setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
			setBackground(ColorScheme.DARKER_GRAY_COLOR);
			setBorder(new EmptyBorder(8, 8, 8, 8));
			setAlignmentX(Component.LEFT_ALIGNMENT);
			if (title != null)
			{
				JLabel heading = new JLabel(wrap(escape(title)));
				heading.setFont(FontManager.getRunescapeBoldFont());
				heading.setForeground(Color.WHITE);
				add(heading);
				add(Box.createVerticalStrut(4));
			}
		}

		@Override
		public Component add(Component component)
		{
			if (component instanceof JComponent)
			{
				((JComponent) component).setAlignmentX(Component.LEFT_ALIGNMENT);
			}
			return super.add(component);
		}

		/** A row that stretches to the card's width. */
		void addWide(JComponent component)
		{
			component.setAlignmentX(Component.LEFT_ALIGNMENT);
			component.setMaximumSize(new Dimension(Integer.MAX_VALUE, component.getPreferredSize().height));
			super.add(component);
		}

		void gap()
		{
			add(Box.createVerticalStrut(6));
		}

		@Override
		public Dimension getMaximumSize()
		{
			return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
		}
	}

	/** Lays out cards top to bottom with a gap between. */
	static JPanel column()
	{
		JPanel column = new JPanel();
		column.setLayout(new BoxLayout(column, BoxLayout.Y_AXIS));
		column.setOpaque(false);
		return column;
	}

	static void addCard(JPanel column, JComponent card)
	{
		if (column.getComponentCount() > 0)
		{
			column.add(Box.createVerticalStrut(GAP));
		}
		card.setAlignmentX(Component.LEFT_ALIGNMENT);
		column.add(card);
	}

	static JLabel heading(String text)
	{
		JLabel label = new JLabel(wrap(escape(text)));
		label.setFont(FontManager.getRunescapeFont());
		label.setForeground(Color.WHITE);
		return label;
	}

	/** A coloured dot and wrapped text. */
	static JLabel status(Color colour, String text)
	{
		JLabel label = new JLabel(wrap(dot(colour) + " " + escape(text)));
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(colour == QUIET ? TEXT : colour);
		return label;
	}

	static JLabel check(boolean done, String doneText, String todoText)
	{
		JLabel label = new JLabel(wrap((done ? "✔ " : "✖ ") + escape(done ? doneText : todoText)));
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(done ? GOOD : TODO);
		label.setBorder(new EmptyBorder(1, 0, 1, 0));
		return label;
	}

	/** Wrapped small text. */
	static JLabel small(String text, Color colour)
	{
		JLabel label = new JLabel(wrap(escape(text)));
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(colour);
		return label;
	}

	/** Single-line text that doesn't wrap. */
	static JLabel plain(String text, Color colour)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(colour);
		return label;
	}

	static JLabel badge(String text, Color colour)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setOpaque(true);
		label.setBackground(colour);
		label.setForeground(Color.BLACK);
		label.setBorder(BorderFactory.createEmptyBorder(1, 4, 1, 4));
		return label;
	}

	/** A dot, a name that is cut short when long, and a right-hand value. */
	static JPanel dotRow(Color colour, String text, String right, String tooltip)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setOpaque(false);
		row.setBorder(new EmptyBorder(1, 0, 1, 0));
		row.setToolTipText(tooltip);
		JLabel dot = plain("●", colour);
		dot.setToolTipText(tooltip);
		row.add(dot, BorderLayout.WEST);
		JLabel what = plain(text, TEXT);
		what.setToolTipText(tooltip != null ? tooltip : text);
		what.setMinimumSize(new Dimension(0, what.getPreferredSize().height));
		what.setPreferredSize(new Dimension(0, what.getPreferredSize().height));
		row.add(what, BorderLayout.CENTER);
		if (right != null)
		{
			row.add(plain(right, QUIET), BorderLayout.EAST);
		}
		return row;
	}

	/** A heading above a group of cards. */
	static JLabel section(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(HIGHLIGHT);
		return label;
	}

	/** Clickable text, for actions that don't need a full button. */
	static JLabel link(String text, Runnable action)
	{
		JLabel label = plain(text, HIGHLIGHT);
		label.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
		label.addMouseListener(new java.awt.event.MouseAdapter()
		{
			@Override
			public void mouseClicked(java.awt.event.MouseEvent e)
			{
				action.run();
			}

			@Override
			public void mouseEntered(java.awt.event.MouseEvent e)
			{
				label.setForeground(Color.WHITE);
			}

			@Override
			public void mouseExited(java.awt.event.MouseEvent e)
			{
				label.setForeground(HIGHLIGHT);
			}
		});
		return label;
	}

	/** One line with something on the left and something on the right; either can be null. */
	static JPanel spread(JComponent left, JComponent right)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setOpaque(false);
		row.setBorder(new EmptyBorder(1, 0, 1, 0));
		if (left != null)
		{
			row.add(left, BorderLayout.WEST);
		}
		if (right != null)
		{
			row.add(right, BorderLayout.EAST);
		}
		return row;
	}

	/** A label on the left and its value on the right. */
	static JPanel statRow(String label, String value)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setOpaque(false);
		row.setBorder(new EmptyBorder(1, 0, 1, 0));
		row.add(plain(label, QUIET), BorderLayout.WEST);
		row.add(plain(value, TEXT), BorderLayout.EAST);
		return row;
	}

	/** A leaderboard position, a name that is cut short when long, and a right-hand value. The member's own row stands out. */
	static JPanel rankRow(Integer rank, String name, String value, boolean mine)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setOpaque(false);
		row.setBorder(new EmptyBorder(1, 0, 1, 0));
		JLabel place = plain(rank != null ? rank + "." : "-", QUIET);
		place.setPreferredSize(new Dimension(RANK_WIDTH, place.getPreferredSize().height));
		row.add(place, BorderLayout.WEST);
		JLabel who = plain(escape(name), mine ? HIGHLIGHT : TEXT);
		who.setToolTipText(name);
		who.setMinimumSize(new Dimension(0, who.getPreferredSize().height));
		who.setPreferredSize(new Dimension(0, who.getPreferredSize().height));
		row.add(who, BorderLayout.CENTER);
		row.add(plain(escape(value), mine ? HIGHLIGHT : TEXT), BorderLayout.EAST);
		return row;
	}

	static JButton button(String text, Runnable action)
	{
		JButton button = new JButton(text);
		button.setFocusPainted(false);
		button.addActionListener(e -> action.run());
		return button;
	}

	static String wrap(String html)
	{
		return "<html><div style='width:" + TEXT_WIDTH + "px'>" + html + "</div></html>";
	}

	static String dot(Color colour)
	{
		return "<span style='color:" + hex(colour) + "'>●</span>";
	}

	static String hex(Color colour)
	{
		return String.format("#%02x%02x%02x", colour.getRed(), colour.getGreen(), colour.getBlue());
	}

	static String escape(String text)
	{
		return text == null ? "" : text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.asgardians;

import java.util.ArrayList;
import java.util.List;

/**
 * Decides what to do when RuneLite's stored PBs change. Pure logic so it can be tested; the plugin feeds it events.
 *
 * <p>RuneLite's Chat Commands plugin parses every PB message and the Adventure Log counters page and writes the result
 * to its "personalbest" store. Mirroring that store means the plugin tracks exactly what RuneLite shows, including
 * team sizes and precise times, without parsing the messages a second time.
 */
class PbTracker
{
	/** A store change this close to a "(new personal best)" message is a live PB. */
	static final long NEW_PB_WINDOW_MILLIS = 10_000;
	/** Other changes (Adventure Log counters, corrections) are gathered and sent as one full sync this long after the last. */
	static final long SYNC_DEBOUNCE_MILLIS = 5_000;

	interface Store
	{
		/** Every key in the current account's "personalbest" store. */
		List<String> keys();

		String value(String key);

		/** Kill count RuneLite stores for a boss, or null. */
		Integer killCount(String boss);
	}

	private final Store store;
	private long lastNewPbMessage = -NEW_PB_WINDOW_MILLIS - 1;
	private long syncDueAt = -1;

	PbTracker(Store store)
	{
		this.store = store;
	}

	/** Call for every game message; remembers when the last "(new personal best)" was seen. */
	void chatMessage(String message, long now)
	{
		if (message.contains("(new personal best)"))
		{
			lastNewPbMessage = now;
		}
	}

	/**
	 * Call when RuneLite's "personalbest" store changes for the logged-in account.
	 *
	 * @return the PB to send right away as a record, or null when it will go in the next full sync instead
	 */
	PersonalBest changed(String key, String newValue, long now)
	{
		PersonalBest pb = PersonalBest.parse(key, newValue);
		if (pb == null)
		{
			return null;
		}
		if (now - lastNewPbMessage <= NEW_PB_WINDOW_MILLIS)
		{
			pb.setNewPb(true);
			pb.setKc(store.killCount(pb.getBoss()));
			return pb;
		}
		requestSync(now);
		return null;
	}

	/** Schedules a full sync after the debounce, pushing it back if one is already waiting. */
	void requestSync(long now)
	{
		syncDueAt = now + SYNC_DEBOUNCE_MILLIS;
	}

	/** Schedules a full sync straight away (login, button). */
	void requestSyncNow(long now)
	{
		syncDueAt = now;
	}

	boolean syncDue(long now)
	{
		return syncDueAt >= 0 && now >= syncDueAt;
	}

	void syncStarted()
	{
		syncDueAt = -1;
	}

	/** Every PB in the store, with kill counts. */
	List<PersonalBest> snapshot()
	{
		List<PersonalBest> all = new ArrayList<>();
		for (String key : store.keys())
		{
			PersonalBest pb = PersonalBest.parse(key, store.value(key));
			if (pb != null)
			{
				pb.setKc(store.killCount(pb.getBoss()));
				all.add(pb);
			}
		}
		return all;
	}
}

package com.asgardians;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Data;

/**
 * One personal best as RuneLite's Chat Commands plugin stores it: config group "personalbest", RS profile scoped,
 * key = lowercase boss name with an optional team size suffix ("chambers of xeric 3 players", "theatre of blood solo"),
 * value = seconds.
 */
@Data
class PersonalBest
{
	static final String CONFIG_GROUP = "personalbest";
	static final String KC_CONFIG_GROUP = "killcount";

	/** "solo", "3 players", "11-15 players", "24+ players". */
	private static final Pattern TEAM_SUFFIX = Pattern.compile("^(.+?) (solo|\\d+(?:-\\d+|\\+)? players)$");
	private static final double TICK_SECONDS = 0.6;

	/** RuneLite's key, exactly as stored. Unique per boss and team size. */
	private final String key;
	/** The key without its team size. */
	private final String boss;
	/** "1" for solo, "3", "11-15", "24+"; null when the PB isn't for a team size. */
	private final String teamSize;
	private final double seconds;
	/** Game ticks, when the time is precise and a whole number of ticks. */
	private final Integer ticks;
	/** False when the time is whole seconds, which may be a rounded (non-precise) time. */
	private final boolean precise;
	private Integer kc;
	/** True when this came from a "(new personal best)" message just now, rather than a sync. */
	private boolean newPb;

	static PersonalBest of(String key, double seconds)
	{
		String boss = key;
		String teamSize = null;
		Matcher m = TEAM_SUFFIX.matcher(key);
		if (m.matches())
		{
			boss = m.group(1);
			String suffix = m.group(2);
			teamSize = suffix.equals("solo") ? "1" : suffix.substring(0, suffix.length() - " players".length());
		}
		boolean precise = seconds != Math.floor(seconds);
		Integer ticks = null;
		if (precise)
		{
			double t = seconds / TICK_SECONDS;
			long rounded = Math.round(t);
			if (Math.abs(t - rounded) < 0.02)
			{
				ticks = (int) rounded;
			}
		}
		return new PersonalBest(key, boss, teamSize, seconds, ticks, precise);
	}

	/** Parses a stored value, or returns null for anything that isn't a positive number of seconds. */
	static PersonalBest parse(String key, String value)
	{
		if (key == null || value == null)
		{
			return null;
		}
		try
		{
			double seconds = Double.parseDouble(value);
			return seconds > 0 ? of(key, seconds) : null;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	String display()
	{
		int whole = (int) seconds;
		String time = whole >= 3600
			? String.format("%d:%02d:%02d", whole / 3600, whole / 60 % 60, whole % 60)
			: String.format("%d:%02d", whole / 60, whole % 60);
		if (precise)
		{
			time += String.format(".%02d", Math.round((seconds - whole) * 100) % 100);
		}
		return key + " " + time;
	}
}

package com.asgardians;

import java.util.Arrays;
import java.util.Locale;
import java.util.Set;
import java.util.stream.Collectors;
import net.runelite.client.util.QuantityFormatter;

/** Turns the member's profile into the words the Connection card shows. */
final class ProfileText
{
	/** The ranks earned over time. Staff and honorary ranks aren't on this ladder, so they have no "next rank". */
	private static final Set<String> LADDER = Set.of("opal", "sapphire", "emerald", "ruby", "diamond", "dragonstone",
		"onyx", "zenyte");

	private ProfileText()
	{
	}

	/** "deputy_owner" becomes "Deputy Owner", "og_gamer" becomes "OG Gamer". */
	static String rank(String rank)
	{
		if (rank == null || rank.isEmpty())
		{
			return "Unranked";
		}
		return Arrays.stream(rank.split("[_ ]+"))
			.map(word -> word.equalsIgnoreCase("og") ? "OG"
				: word.substring(0, 1).toUpperCase(Locale.UK) + word.substring(1).toLowerCase(Locale.UK))
			.collect(Collectors.joining(" "));
	}

	/** 976 days becomes "2y 8m", the way the website's member list shows it. */
	static String time(int days)
	{
		if (days < 30)
		{
			return days + "d";
		}
		int years = days / 365;
		int months = (days % 365) / 30;
		if (years == 0)
		{
			return months + "m";
		}
		return months == 0 ? years + "y" : years + "y " + months + "m";
	}

	static String amount(long value)
	{
		return QuantityFormatter.quantityToStackSize(value);
	}

	/** How to link Discord, or null when it's already linked. */
	static String discordHelp(ClanData.Me me)
	{
		if (me.isDiscordLinked())
		{
			return null;
		}
		if (me.getDiscordHelp() != null)
		{
			return me.getDiscordHelp();
		}
		return "To link Discord: in the Asgardians Discord, open the welcome panel, choose Set your name and enter "
			+ (me.getRsn() != null ? me.getRsn() : "your RSN") + " exactly.";
	}

	/** What's left for the next rank, or null when the member isn't on the ladder or there's nothing above them. */
	static String nextRank(ClanData.Me me)
	{
		ClanData.NextRank next = me.getNextRank();
		if (next == null || next.getName() == null || me.getRank() == null
			|| !LADDER.contains(me.getRank().toLowerCase(Locale.UK)))
		{
			return null;
		}
		long credit = next.getCreditRemaining() != null ? next.getCreditRemaining() : 0;
		int days = next.getDaysRemaining() != null ? next.getDaysRemaining() : 0;
		if (credit <= 0 && days <= 0)
		{
			return "Ready for " + rank(next.getName()) + ". Staff will promote you.";
		}
		StringBuilder left = new StringBuilder();
		if (credit > 0)
		{
			left.append(amount(credit)).append(" credit");
		}
		if (days > 0)
		{
			left.append(left.length() > 0 ? " and " : "").append(days).append(days == 1 ? " day" : " days");
		}
		return "Next rank " + rank(next.getName()) + ": " + left + " to go";
	}
}

package com.asgardians;

import java.util.List;
import java.util.UUID;
import lombok.Data;

/**
 * One generic drop-recorder record. The server decides what each record counts for (drops page, clog page, events),
 * so the plugin records what happened and nothing more. Null fields are left out of the JSON.
 */
@Data
class Record
{
	enum Type
	{
		loot,
		pet,
		clog,
		pb,
		death
	}

	@Data
	static class Source
	{
		private final String name;
		private final Integer npcId;
		private Integer kc;
	}

	@Data
	static class Item
	{
		private final int id;
		private final String name;
		private final int qty;
		private final long gePrice;
	}

	private final String id = UUID.randomUUID().toString();
	private final Type type;
	/** ISO-8601 UTC time the event happened in game. */
	private final String at;
	private final int world;

	private Source source;
	private List<Item> items;
	/** How many players were in the instance, including the player. Only set for group content; never names. */
	private Integer partySize;

	/** Pet records: the pet's name from the clan broadcast, when one arrived. */
	private String petName;
	private Boolean duplicate;

	/** Clog records. */
	private String itemName;
	private Integer itemId;
	private Integer completed;

	/** PB records. */
	private PersonalBest pb;

	/** Death records. */
	private Death death;

	/** True when a screenshot is uploaded with this record. */
	private boolean screenshot;

	/** Total GE value of the items, used for screenshot rules and the panel. Not sent. */
	transient long totalValue;
	/** Epoch millis when the record was created. Not sent. */
	transient long createdMillis;
	/** Still waiting for its screenshot; the uploader holds it back until it arrives or times out. Not sent. */
	transient volatile boolean awaitingScreenshot;

	String describe()
	{
		switch (type)
		{
			case pet:
				return "Pet" + (petName != null ? ": " + petName : "");
			case clog:
				return "Clog: " + itemName;
			case pb:
				return "PB: " + (pb != null ? pb.display() : "");
			case death:
				if (death == null || death.getKiller() == null || death.getKiller().getName() == null)
				{
					return "Death";
				}
				return "Death: " + death.getKiller().getName();
			default:
				if (items == null || items.isEmpty())
				{
					return "Loot";
				}
				Item best = items.get(0);
				for (Item item : items)
				{
					if ((long) item.getQty() * item.getGePrice() > (long) best.getQty() * best.getGePrice())
					{
						best = item;
					}
				}
				return best.getName() + (source != null ? " (" + source.getName() + ")" : "");
		}
	}
}

package com.asgardians;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.HashMap;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;

/**
 * Records waiting to be sent, plus the last 20 for the panel. Thread-safe: the client thread adds, the upload thread drains.
 */
class RecordQueue
{
	static final int MAX_QUEUED = 1000;
	static final int BATCH_SIZE = 50;
	static final int HISTORY = 20;
	/** How long a record waits for its screenshot before going without one. */
	static final long SCREENSHOT_WAIT_MILLIS = 10_000;

	enum Status
	{
		QUEUED,
		SENT,
		/** Not sent yet; will retry. */
		FAILED,
		/** The server refused this record; it won't be sent again. */
		REJECTED
	}

	static class Entry
	{
		final Record record;
		volatile Status status = Status.QUEUED;
		/** The server's reason, for rejected records. */
		volatile String reason;

		Entry(Record record)
		{
			this.record = record;
		}
	}

	private final Deque<Record> pending = new ArrayDeque<>();
	/**
	 * After the server rejects a batch, its records are retried one per batch so only the bad one is dropped. This many
	 * of the next batches are single records.
	 */
	private int sendSingly;
	private final Map<String, byte[]> screenshots = new HashMap<>();
	private final LinkedList<Entry> history = new LinkedList<>();
	private final Map<String, Entry> historyById = new HashMap<>();

	synchronized void add(Record record)
	{
		if (pending.size() >= MAX_QUEUED)
		{
			Record dropped = pending.pollFirst();
			if (dropped != null)
			{
				screenshots.remove(dropped.getId());
			}
		}
		pending.addLast(record);
		Entry entry = new Entry(record);
		history.addFirst(entry);
		historyById.put(record.getId(), entry);
		while (history.size() > HISTORY)
		{
			historyById.remove(history.removeLast().record.getId());
		}
	}

	/** The record goes without a picture, straight away rather than after the wait. */
	synchronized void noScreenshot(String recordId)
	{
		for (Record record : pending)
		{
			if (record.getId().equals(recordId))
			{
				record.awaitingScreenshot = false;
				record.setScreenshot(false);
				return;
			}
		}
	}

	synchronized void attachScreenshot(String recordId, byte[] png)
	{
		for (Record record : pending)
		{
			if (record.getId().equals(recordId))
			{
				screenshots.put(recordId, png);
				record.awaitingScreenshot = false;
				return;
			}
		}
	}

	/**
	 * Takes the next batch, oldest first. A record still waiting for its screenshot stops the batch there, so records stay
	 * in order, unless it has waited too long, in which case it goes without one.
	 */
	synchronized List<Record> takeBatch(long now)
	{
		List<Record> batch = new ArrayList<>();
		int limit = sendSingly > 0 ? 1 : BATCH_SIZE;
		while (!pending.isEmpty() && batch.size() < limit)
		{
			Record next = pending.peekFirst();
			if (next.awaitingScreenshot)
			{
				if (now - next.createdMillis < SCREENSHOT_WAIT_MILLIS)
				{
					break;
				}
				next.awaitingScreenshot = false;
				next.setScreenshot(false);
			}
			batch.add(pending.pollFirst());
		}
		if (!batch.isEmpty() && sendSingly > 0)
		{
			sendSingly--;
		}
		return batch;
	}

	/**
	 * The server refused a batch it couldn't accept. A single record is dropped and marked rejected; a larger batch goes
	 * back to be retried one record at a time, so good records aren't lost with a bad one.
	 *
	 * @return true when the batch was put back to retry singly, false when its one record was dropped
	 */
	synchronized boolean rejected(List<Record> batch, String reason)
	{
		if (batch.size() > 1)
		{
			for (int i = batch.size() - 1; i >= 0; i--)
			{
				pending.addFirst(batch.get(i));
			}
			sendSingly = Math.max(sendSingly, batch.size());
			mark(batch, Status.FAILED);
			return true;
		}
		for (Record record : batch)
		{
			screenshots.remove(record.getId());
			Entry entry = historyById.get(record.getId());
			if (entry != null)
			{
				entry.status = Status.REJECTED;
				entry.reason = reason;
			}
		}
		return false;
	}

	synchronized Map<String, byte[]> screenshotsFor(List<Record> batch)
	{
		Map<String, byte[]> out = new HashMap<>();
		for (Record record : batch)
		{
			byte[] png = screenshots.get(record.getId());
			if (png != null && record.isScreenshot())
			{
				out.put(record.getId(), png);
			}
		}
		return out;
	}

	/** Puts a failed batch back at the front, in its original order. */
	synchronized void requeue(List<Record> batch)
	{
		for (int i = batch.size() - 1; i >= 0; i--)
		{
			pending.addFirst(batch.get(i));
		}
		mark(batch, Status.FAILED);
	}

	synchronized void sent(List<Record> batch)
	{
		for (Record record : batch)
		{
			screenshots.remove(record.getId());
		}
		mark(batch, Status.SENT);
	}

	synchronized int size()
	{
		return pending.size();
	}

	synchronized List<Entry> recent()
	{
		return Collections.unmodifiableList(new ArrayList<>(history));
	}

	synchronized void clear()
	{
		pending.clear();
		screenshots.clear();
	}

	private void mark(List<Record> batch, Status status)
	{
		for (Record record : batch)
		{
			Entry entry = historyById.get(record.getId());
			if (entry != null)
			{
				entry.status = status;
			}
		}
	}
}

package com.asgardians;

import lombok.Data;

/** Settings served by GET /api/v1/plugin/config. The defaults apply until the server answers, or if it can't be reached. */
@Data
class ServerSettings
{
	@Data
	static class Screenshots
	{
		private long minLootValue = 1_000_000;
		private boolean pets = true;
		private boolean clog = true;
		private boolean pbs = true;
		private boolean deaths = true;
		/** Item IDs that always get a screenshot whatever they're worth, such as items a live event is watching for. */
		private java.util.Set<Integer> watch = java.util.Set.of();

		/** Loot gets a screenshot when it's valuable enough or includes a watched item. */
		boolean wantsLoot(Record record)
		{
			if (record.totalValue >= minLootValue)
			{
				return true;
			}
			if (watch != null && record.getItems() != null)
			{
				for (Record.Item item : record.getItems())
				{
					if (watch.contains(item.getId()))
					{
						return true;
					}
				}
			}
			return false;
		}
	}

	private Screenshots screenshots = new Screenshots();
	/** Stops all sending without a hub update. */
	private boolean killSwitch;
	/** Oldest plugin version the server still accepts. */
	private String minVersion;
}

package com.asgardians;

import java.awt.Component;
import java.awt.GridLayout;
import java.time.DateTimeException;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JComponent;
